// ---------------------------------------------------------------------
// PDF object model
// ---------------------------------------------------------------------
interface PName { t: "name"; v: string }
interface PStr { t: "str"; v: string }          // latin1 (one char per byte)
interface PRef { t: "ref"; n: number; g: number }
interface PArr { t: "arr"; v: PObj[] }
interface PDict { t: "dict"; m: Map<string, PObj> }
interface PKw { t: "kw"; v: string }            // keyword / content-stream operator
// n/g: object and generation number (key for decryption); start: offset of the data in the file;
// exactLen: raw was cut by a direct /Length (false = cut at "endstream", may be refined later)
interface PStream { t: "stream"; d: PDict; raw: string; id: number; n: number; g: number; start: number; exactLen: boolean }
type PObj = number | boolean | null | PName | PStr | PRef | PArr | PDict | PKw | PStream;

function isName(o: PObj): o is PName { return typeof o === "object" && o !== null && o.t === "name"; }
function isStr(o: PObj): o is PStr { return typeof o === "object" && o !== null && o.t === "str"; }
function isRef(o: PObj): o is PRef { return typeof o === "object" && o !== null && o.t === "ref"; }
function isArr(o: PObj): o is PArr { return typeof o === "object" && o !== null && o.t === "arr"; }
function isDict(o: PObj): o is PDict { return typeof o === "object" && o !== null && o.t === "dict"; }
function isKw(o: PObj): o is PKw { return typeof o === "object" && o !== null && o.t === "kw"; }
function isStream(o: PObj): o is PStream { return typeof o === "object" && o !== null && o.t === "stream"; }
function isNum(o: PObj): o is number { return typeof o === "number"; }

function mkName(v: string): PName { return { t: "name", v: v }; }
function mkDict(): PDict { return { t: "dict", m: new Map<string, PObj>() }; }

function isWs(c: number): boolean {
  // PDF white space (character classes)
  return c === 32 || c === 10 || c === 13 || c === 9 || c === 12 || c === 0;
}
function isDelim(c: number): boolean {
  // ( ) < > [ ] { } / %
  return c === 40 || c === 41 || c === 60 || c === 62 || c === 91 || c === 93 || c === 123 || c === 125 || c === 47 || c === 37;
}
function isRegular(c: number): boolean {
  return !isWs(c) && !isDelim(c);
}

// ---------------------------------------------------------------------
// Lexer / parser over a latin1 string
// ---------------------------------------------------------------------
// Lexer.unterminated: a literal string ran to the end of the input
class Lexer {
  s: string;
  pos: number;
  unterminated: boolean;
  constructor(s: string, pos: number) {
    this.s = s;
    this.pos = pos;
    this.unterminated = false;
  }
  skipWs(): void {
    const s = this.s;
    while (this.pos < s.length) {
      const c = s.charCodeAt(this.pos);
      if (isWs(c)) this.pos++;
      else if (c === 37) { // % comment
        while (this.pos < s.length) {
          const d = s.charCodeAt(this.pos);
          if (d === 10 || d === 13) break;
          this.pos++;
        }
      } else break;
    }
  }
  peekByte(): number {
    return this.pos < this.s.length ? this.s.charCodeAt(this.pos) : -1;
  }
  readRegular(): string {
    const start = this.pos;
    while (this.pos < this.s.length && isRegular(this.s.charCodeAt(this.pos))) this.pos++;
    return this.s.substring(start, this.pos);
  }
  parse(depth: number): PObj | null {
    // Parses one object. Keywords are returned as PKw. Returns null at EOF.
    this.skipWs();
    const s = this.s;
    if (this.pos >= s.length) return null;
    if (depth > 300) throw new Error("nesting too deep");
    const c = s.charCodeAt(this.pos);
    if (c === 47) { // '/' name
      this.pos++;
      let raw = this.readRegular();
      if (raw.indexOf("#") >= 0) {
        let dec = "";
        for (let i = 0; i < raw.length; i++) {
          const h = raw.substring(i + 1, i + 3);
          if (raw.charAt(i) === "#" && /^[0-9A-Fa-f]{2}$/.test(h)) { dec += String.fromCharCode(parseInt(h, 16)); i += 2; }
          else dec += raw.charAt(i);
        }
        raw = dec;
      }
      return mkName(raw);
    }
    if (c === 40) return this.parseLiteralString(); // '('
    if (c === 60) { // '<'
      if (s.charCodeAt(this.pos + 1) === 60) return this.parseDict(depth);
      return this.parseHexString();
    }
    if (c === 91) { // '['
      this.pos++;
      const arr: PObj[] = [];
      for (;;) {
        this.skipWs();
        if (this.pos >= s.length) break;
        if (s.charCodeAt(this.pos) === 93) { this.pos++; break; }
        const o = this.parse(depth + 1);
        if (o === null) { if (this.pos >= s.length) break; arr.push(null); continue; }
        if (isKw(o)) {
          if (o.v === "R" && arr.length >= 2) {
            const g = arr.pop(), n = arr.pop();
            if (n !== undefined && g !== undefined && isNum(n) && isNum(g)) { arr.push({ t: "ref", n: n, g: g }); continue; }
          }
          if (o.v === "endobj" || o.v === "endstream" || o.v === "stream") { break; }
          continue; // ignore stray keywords inside arrays
        }
        arr.push(o);
      }
      return { t: "arr", v: arr };
    }
    if (c === 93 || c === 62 || c === 41 || c === 123 || c === 125) { // stray delimiters
      this.pos++;
      return this.parse(depth);
    }
    if ((c >= 48 && c <= 57) || c === 43 || c === 45 || c === 46) { // number
      const tok = this.readRegular();
      const v = parseFloat(tok);
      return isNaN(v) ? 0 : v;
    }
    const kw = this.readRegular();
    if (kw.length === 0) { this.pos++; return this.parse(depth); }
    if (kw === "true") return true;
    if (kw === "false") return false;
    if (kw === "null") return null as PObj;
    return { t: "kw", v: kw };
  }
  parseDict(depth: number): PDict {
    const s = this.s;
    this.pos += 2;
    const d = mkDict();
    let pendingKey: string | null = null;
    const vals: PObj[] = [];
    // (the key/value bookkeeping stays inline: a local helper could run out of order when the runtime makes it async)
    for (;;) {
      this.skipWs();
      if (this.pos >= s.length) break;
      if (s.charCodeAt(this.pos) === 62) { // '>'
        this.pos++;
        if (s.charCodeAt(this.pos) === 62) this.pos++;
        break;
      }
      const o = this.parse(depth + 1);
      if (o === null) { if (this.pos >= s.length) break; vals.push(null); continue; }
      if (isName(o) && (pendingKey === null || vals.length > 0)) {
        if (pendingKey !== null) d.m.set(pendingKey, vals.length > 0 ? vals[vals.length - 1] : null);
        vals.length = 0;
        pendingKey = o.v;
        continue;
      }
      if (isKw(o)) {
        if (o.v === "R" && vals.length >= 2) {
          const g = vals.pop(), n = vals.pop();
          if (n !== undefined && g !== undefined && isNum(n) && isNum(g)) { vals.push({ t: "ref", n: n, g: g }); continue; }
        }
        if (o.v === "endobj" || o.v === "stream" || o.v === "endstream") {
          // malformed dict without closing >> – rewind so the caller sees the keyword
          this.pos -= o.v.length;
          break;
        }
        continue;
      }
      vals.push(o);
    }
    if (pendingKey !== null) d.m.set(pendingKey, vals.length > 0 ? vals[vals.length - 1] : null);
    return d;
  }
  parseLiteralString(): PStr {
    const s = this.s;
    this.pos++;
    let depth = 1;
    let out = "";
    while (this.pos < s.length) {
      const c = s.charCodeAt(this.pos++);
      if (c === 92) { // backslash
        const e = s.charCodeAt(this.pos++);
        if (e === 110) out += "\n";
        else if (e === 114) out += "\r";
        else if (e === 116) out += "\t";
        else if (e === 98) out += "\b";
        else if (e === 102) out += "\f";
        else if (e >= 48 && e <= 55) {
          let oct = e - 48;
          for (let k = 0; k < 2; k++) {
            const d = s.charCodeAt(this.pos);
            if (d >= 48 && d <= 55) { oct = oct * 8 + (d - 48); this.pos++; } else break;
          }
          out += String.fromCharCode(oct & 0xff);
        } else if (e === 13) {
          if (s.charCodeAt(this.pos) === 10) this.pos++;
        } else if (e === 10) {
          // line continuation
        } else out += String.fromCharCode(e);
      } else if (c === 40) { depth++; out += "("; }
      else if (c === 41) { depth--; if (depth === 0) break; out += ")"; }
      else out += String.fromCharCode(c);
    }
    if (depth > 0) this.unterminated = true;
    return { t: "str", v: out };
  }
  parseHexString(): PStr {
    const s = this.s;
    this.pos++;
    let out = "";
    let digit = -1;
    while (this.pos < s.length) {
      const c = s.charCodeAt(this.pos++);
      if (c === 62) break;
      let v = -1;
      if (c >= 48 && c <= 57) v = c - 48;
      else if (c >= 65 && c <= 70) v = c - 55;
      else if (c >= 97 && c <= 102) v = c - 87;
      else continue;
      if (digit < 0) digit = v;
      else { out += String.fromCharCode((digit << 4) | v); digit = -1; }
    }
    if (digit >= 0) out += String.fromCharCode(digit << 4);
    return { t: "str", v: out };
  }
}

// ---------------------------------------------------------------------
// Document: object map (brute-force scan, later definitions win),
// object streams, trailer, decryption, stream decoding, page tree
// ---------------------------------------------------------------------
interface ObjEntry { obj: PObj; pos: number; gen: number }

// Standard security handler opened with the empty user password
interface CryptState {
  key: Uint8Array;               // file encryption key
  rev: number;                   // /R
  stmF: string;                  // method for streams: none / rc4 / aesv2 / aesv3
  strF: string;                  // method for strings
  filters: Map<string, string>;  // crypt filter name -> method (streams with a /Crypt filter)
  encryptMetadata: boolean;
  encNum: number;                // object number of the encryption dictionary (-1 = direct)
}

interface PageRef { dict: PDict; resources: PDict | null; box: number[] }

// keys not followed when collecting what the pages use: back links (P, Parent of annotations / fields),
// signature and field values, actions, destinations, metadata, thumbnails
const SIGN_SKIP_KEYS = ["P", "V", "A", "AA", "Dest", "Metadata", "Thumb", "PieceInfo", "B", "SV", "Lock", "Reference", "IRT", "StructParent", "StructParents"];

function samePdfObj(a: PObj, b: PObj, depth: number): boolean {
  // structural equality of two parsed objects (a stream: its dictionary and its raw data)
  if (a === b) return true;
  if (a === null || b === null || typeof a !== "object" || typeof b !== "object") return false;
  if (depth > 40 || a.t !== b.t) return false;
  if (a.t === "ref") return isRef(b) && a.n === b.n && a.g === b.g;
  if (a.t === "name" || a.t === "str" || a.t === "kw") return (isName(b) || isStr(b) || isKw(b)) && a.v === b.v;
  if (a.t === "arr") {
    if (!isArr(b) || a.v.length !== b.v.length) return false;
    for (let i = 0; i < a.v.length; i++) if (!samePdfObj(a.v[i], b.v[i], depth + 1)) return false;
    return true;
  }
  const da = a.t === "stream" ? a.d : a.t === "dict" ? a : null;
  const db = isStream(b) ? b.d : isDict(b) ? b : null;
  if (da === null || db === null || da.m.size !== db.m.size) return false;
  if (isStream(a) && (!isStream(b) || a.raw !== b.raw)) return false;
  for (const [k, v] of Array.from(da.m.entries())) {
    const w = db.m.get(k);
    if (w === undefined || !samePdfObj(v, w, depth + 1)) return false;
  }
  return true;
}

const PDF_PASSWORD_PAD = [0x28, 0xbf, 0x4e, 0x5e, 0x4e, 0x75, 0x8a, 0x41, 0x64, 0x00, 0x4e, 0x56, 0xff, 0xfa, 0x01, 0x08, 0x2e, 0x2e, 0x00, 0xb6, 0xd0, 0x68, 0x3e, 0x80, 0x2f, 0x0c, 0xa9, 0xfe, 0x64, 0x53, 0x69, 0x7a];

// PdfDoc fields:
//   encrypted: the trailer names an /Encrypt dictionary
//   fileId: first element of the trailer /ID
//   cryptStatus: none / decrypted / password / certificate / unsupported
//   incomplete: reasons why the extracted text may be partial
//   ocOff: optional-content groups that are OFF by default
//   history: earlier definitions of objects that a later one replaced (incremental updates)
//   cryptStatus "protected": an unencrypted wrapper around an encrypted payload (ISO 32000-2, e.g. Microsoft Purview)
class PdfDoc {
  s: string;
  objs: Map<number, ObjEntry>;
  streamCache: Map<number, Uint8Array>;
  failedStreams: Set<number>;
  trailerRoot: PRef | null;
  encrypted: boolean;
  warnings: string[];
  nextStreamId: number;
  encryptObj: PObj | null;
  fileId: string;
  infoObj: PObj | null;
  crypt: CryptState | null;
  cryptStatus: string;
  cryptDetail: string;
  incomplete: string[];
  ocOff: Set<PDict>;
  ocUsed: boolean;
  keyCache: Map<string, Uint8Array>;
  history: Map<number, ObjEntry[]>;

  constructor(s: string) {
    this.s = s;
    this.objs = new Map<number, ObjEntry>();
    this.streamCache = new Map<number, Uint8Array>();
    this.failedStreams = new Set<number>();
    this.trailerRoot = null;
    this.encrypted = false;
    this.warnings = [];
    this.nextStreamId = 1;
    this.encryptObj = null;
    this.fileId = "";
    this.infoObj = null;
    this.crypt = null;
    this.cryptStatus = "none";
    this.cryptDetail = "";
    this.incomplete = [];
    this.ocOff = new Set<PDict>();
    this.ocUsed = false;
    this.keyCache = new Map<string, Uint8Array>();
    this.history = new Map<number, ObjEntry[]>();
  }

  load(): void {
    // two-phase init keeps the constructor free of heavy work (Office Scripts restriction)
    this.scan();
    if (this.encryptObj !== null) this.setupEncryption();
    if (this.cryptStatus === "none" || this.cryptStatus === "decrypted") {
      this.expandObjectStreams();
      this.loadOptionalContent();
      if (this.hasEncryptedPayload()) this.cryptFail("protected", "encrypted payload");
    }
    const tail = Math.max(0, this.s.length - 4096);
    if (this.s.indexOf("%%EOF", tail) < 0) this.flagIncomplete("no %%EOF at the end of the file (truncated?)");
  }

  flagIncomplete(reason: string): void {
    if (this.incomplete.length < 8 && this.incomplete.indexOf(reason) < 0) this.incomplete.push(reason);
  }

  private scan(): void {
    const s = this.s;
    const re = /(\d+)\s+(\d+)\s+obj\b/g;
    let m: RegExpExecArray | null;
    let guard = 0;
    // one try for the whole scan (each executed try costs milliseconds in Office Scripts); after an exception the
    // scan resumes behind the object that failed
    let num = 0;
    let after = 0;
    for (;;) {
      try {
        while ((m = re.exec(s)) !== null) {
          if (++guard > 500000) { this.flagIncomplete("too many objects"); break; }
          if ((guard & 4095) === 0 && Date.now() > runDeadline) {
            this.warnings.push("time budget exhausted while scanning objects");
            this.flagIncomplete("time budget exhausted");
            break;
          }
          num = parseInt(m[1], 10);
          const gen = parseInt(m[2], 10);
          const start = m.index;
          after = start + m[0].length;
          {
            const lx = new Lexer(s, after);
            let obj = lx.parse(0);
            if (obj !== null && isKw(obj)) obj = null;
            lx.skipWs();
            let end = lx.pos;
            if (isDict(obj) && s.substring(lx.pos, lx.pos + 6) === "stream") {
              const r = this.readStream(obj, lx.pos + 6, num, gen);
              obj = r.stream;
              end = r.end;
            }
            const prevDef = this.objs.get(num);
            if (prevDef !== undefined) this.remember(num, prevDef);
            this.objs.set(num, { obj: obj, pos: start, gen: gen });
            // an unbalanced "(" must not swallow the rest of the file: rescan right after the header, or
            // after the first "endobj" when the parse ran past it (a later ")" closed the broken string)
            const ej = isStream(obj) ? -1 : s.indexOf("endobj", after);
            if (lx.unterminated) { /* keep after */ }
            else if (ej >= 0 && ej + 6 < end) { after = ej + 6; this.flagIncomplete("object " + num + " is malformed"); }
            else after = Math.max(after, end);
          }
          re.lastIndex = after;
        }
        break;
      } catch (e) {
        this.warnings.push("object " + num + ": " + String(e));
        re.lastIndex = after;
      }
    }
    // trailer dictionaries (classic trailers and cross-reference streams), newest last
    const trailers: { d: PDict; pos: number }[] = [];
    const tre = /trailer\s*<</g;
    let tm: RegExpExecArray | null;
    while ((tm = tre.exec(s)) !== null) {
      try {
        const lx = new Lexer(s, tm.index + 7);
        const d = lx.parse(0);
        if (isDict(d)) trailers.push({ d: d, pos: tm.index });
      } catch (e) { /* ignore */ }
    }
    for (const e of Array.from(this.objs.values())) {
      if (isStream(e.obj)) {
        const ty = e.obj.d.m.get("Type");
        if (ty !== undefined && isName(ty) && ty.v === "XRef") trailers.push({ d: e.obj.d, pos: e.pos });
      }
    }
    trailers.sort((a, b) => a.pos - b.pos);
    for (const t of trailers) {
      const root = t.d.m.get("Root");
      if (root !== undefined && isRef(root)) this.trailerRoot = root;
      const enc = t.d.m.get("Encrypt");
      if (enc !== undefined && enc !== null) { this.encrypted = true; this.encryptObj = enc; }
      const info = t.d.m.get("Info");
      if (info !== undefined && info !== null) this.infoObj = info;
      const id = t.d.m.get("ID");
      if (id !== undefined && isArr(id) && id.v.length > 0 && isStr(id.v[0])) this.fileId = (id.v[0] as PStr).v;
    }
  }

  private readStream(d: PDict, p: number, num: number, gen: number): { stream: PStream; end: number } {
    const s = this.s;
    // after the 'stream' keyword: CRLF or LF
    if (s.charCodeAt(p) === 13) p++;
    if (s.charCodeAt(p) === 10) p++;
    const dataStart = p;
    let len = -1;
    const L = d.m.get("Length");
    if (L !== undefined && isNum(L)) len = L;
    // (an indirect /Length is resolved later in streamData)
    let dataEnd = -1;
    if (len >= 0 && dataStart + len <= s.length) {
      const probe = new Lexer(s, dataStart + len);
      probe.skipWs();
      if (s.substring(probe.pos, probe.pos + 9) === "endstream") dataEnd = dataStart + len;
    }
    const exact = dataEnd >= 0;
    if (dataEnd < 0) {
      // fall back to searching the keyword
      let idx = s.indexOf("endstream", dataStart);
      if (idx < 0) {
        idx = s.length;
        this.flagIncomplete("stream " + num + " has no endstream (file truncated?)");
      }
      dataEnd = idx;
      // strip trailing EOL
      if (s.charCodeAt(dataEnd - 1) === 10) dataEnd--;
      if (s.charCodeAt(dataEnd - 1) === 13) dataEnd--;
    }
    const raw = s.substring(dataStart, dataEnd);
    let end = s.indexOf("endstream", dataEnd);
    end = end < 0 ? s.length : end + 9;
    const ej = s.indexOf("endobj", end);
    if (ej >= 0 && ej - end < 4) end = ej + 6;
    return { stream: { t: "stream", d: d, raw: raw, id: this.nextStreamId++, n: num, g: gen, start: dataStart, exactLen: exact }, end: end };
  }

  private setupEncryption(): void {
    // Standard security handler (ISO 32000-2 7.6.4) opened with the empty user password
    const enc = this.dictOf(this.encryptObj === null ? undefined : this.encryptObj);
    if (!enc) { this.cryptFail("unsupported", "encryption dictionary not found"); return; }
    const filter = this.nameOf(enc.m.get("Filter"));
    if (filter.indexOf("PubSec") >= 0) { this.cryptFail("certificate", filter); return; }
    if (filter !== "Standard") { this.cryptFail("unsupported", "security handler " + (filter || "?")); return; }
    const v = this.num(enc.m.get("V"), 0);
    const r = this.num(enc.m.get("R"), 0);
    if (v !== 1 && v !== 2 && v !== 4 && v !== 5) { this.cryptFail("unsupported", "/V " + v); return; }
    const o = this.strBytes(enc.m.get("O"));
    const u = this.strBytes(enc.m.get("U"));
    const p = this.num(enc.m.get("P"), 0) | 0;
    const encryptMetadata = this.resolve(enc.m.get("EncryptMetadata")) !== false;
    const methods = new Map<string, string>();
    methods.set("Identity", "none");
    let cfLen = 0;
    const cf = this.dictOf(enc.m.get("CF"));
    if (cf) {
      for (const [name, val] of Array.from(cf.m.entries())) {
        const cd = this.dictOf(val);
        const cfm = cd ? this.nameOf(cd.m.get("CFM")) : "";
        methods.set(name, cfm === "V2" ? "rc4" : cfm === "AESV2" ? "aesv2" : cfm === "AESV3" ? "aesv3" : cfm === "None" || cfm === "" ? "none" : "?" + cfm);
        if (cd && cfLen === 0) cfLen = this.num(cd.m.get("Length"), 0);
      }
    }
    let stmF = "rc4", strF = "rc4";
    if (v >= 4) {
      const sn = this.nameOf(enc.m.get("StmF")) || "Identity", tn = this.nameOf(enc.m.get("StrF")) || "Identity";
      stmF = methods.get(sn) || "?" + sn;
      strF = methods.get(tn) || "?" + tn;
    }
    if (stmF.charAt(0) === "?" || strF.charAt(0) === "?") { this.cryptFail("unsupported", "crypt filter " + (stmF.charAt(0) === "?" ? stmF : strF).substring(1)); return; }
    // key length in bits (generators sometimes give bytes)
    let lenBits = this.num(enc.m.get("Length"), 0);
    if (lenBits <= 0) lenBits = v <= 2 ? 40 : cfLen > 0 ? cfLen : 128;
    if (lenBits < 40) lenBits *= 8;
    if (lenBits % 8 !== 0 || lenBits > 256) lenBits = 128;
    const empty = new Uint8Array(0);
    let key: Uint8Array;
    if (r >= 2 && r <= 4) {
      const n = r === 2 ? 5 : Math.max(5, Math.min(16, lenBits >> 3));
      const id = latin1ToBytes(this.fileId);
      const pad = new Uint8Array(PDF_PASSWORD_PAD);
      const parts = [pad, o.subarray(0, 32), new Uint8Array([p & 255, (p >>> 8) & 255, (p >>> 16) & 255, (p >>> 24) & 255]), id];
      if (r >= 4 && !encryptMetadata) parts.push(new Uint8Array([255, 255, 255, 255]));
      let h = md5(concatBytes(parts));
      if (r >= 3) for (let i = 0; i < 50; i++) h = md5(h.subarray(0, n));
      key = h.subarray(0, n);
      // the empty password is the user password only if it reproduces /U (algorithms 4 and 5)
      let ok = false;
      if (r === 2) ok = bytesEqual(rc4(key, pad), u, 32);
      else {
        let x = rc4(key, md5(concatBytes([pad, id])));
        const k2 = new Uint8Array(n);
        for (let i = 1; i <= 19; i++) {
          for (let j = 0; j < n; j++) k2[j] = key[j] ^ i;
          x = rc4(k2, x);
        }
        ok = bytesEqual(x, u, 16);
      }
      if (!ok) { this.cryptFail("password", ""); return; }
    } else if (r === 5 || r === 6) {
      const ue = this.strBytes(enc.m.get("UE"));
      if (u.length < 48 || ue.length < 32) { this.cryptFail("unsupported", "/U or /UE too short"); return; }
      const check = pdfPasswordHash(empty, u.subarray(32, 40), empty, r === 6);
      if (!bytesEqual(check, u, 32)) { this.cryptFail("password", ""); return; }
      const ik = pdfPasswordHash(empty, u.subarray(40, 48), empty, r === 6);
      key = aesCbc(ik, new Uint8Array(16), ue.subarray(0, 32), 0, true);
      const perms = this.strBytes(enc.m.get("Perms"));
      if (perms.length >= 16) {
        const dp = aesCbc(key, new Uint8Array(16), perms.subarray(0, 16), 0, true);
        if (dp[9] !== 0x61 || dp[10] !== 0x64 || dp[11] !== 0x62) this.warnings.push("encryption: /Perms check failed");
      }
    } else {
      this.cryptFail("unsupported", "/R " + r);
      return;
    }
    this.crypt = {
      key: key,
      rev: r,
      stmF: stmF,
      strF: strF,
      filters: methods,
      encryptMetadata: encryptMetadata,
      encNum: isRef(this.encryptObj) ? this.encryptObj.n : -1,
    };
    this.cryptStatus = "decrypted";
    this.cryptDetail = "R" + r + " " + stmF;
    this.decryptAllStrings();
  }

  private cryptFail(status: string, detail: string): void {
    this.cryptStatus = status;
    this.cryptDetail = detail;
  }

  private strBytes(o: PObj | undefined): Uint8Array {
    const r = this.resolve(o);
    return isStr(r) ? latin1ToBytes(r.v) : new Uint8Array(0);
  }

  private objectKey(num: number, gen: number, method: string): Uint8Array {
    // per-object key (algorithm 1); AES-256 uses the file key directly
    const c = this.crypt as CryptState;
    if (method === "aesv3" || c.rev >= 5) return c.key;
    const ck = num + "/" + gen + "/" + method;
    const hit = this.keyCache.get(ck);
    if (hit !== undefined) return hit;
    const parts = [c.key, new Uint8Array([num & 255, (num >> 8) & 255, (num >> 16) & 255, gen & 255, (gen >> 8) & 255])];
    if (method === "aesv2") parts.push(new Uint8Array([0x73, 0x41, 0x6c, 0x54])); // "sAlT"
    const k = md5(concatBytes(parts)).subarray(0, Math.min(c.key.length + 5, 16));
    this.keyCache.set(ck, k);
    return k;
  }

  private decryptBytes(data: Uint8Array, num: number, gen: number, method: string): Uint8Array {
    if (method === "none" || !this.crypt) return data;
    const key = this.objectKey(num, gen, method);
    if (method === "rc4") return rc4(key, data);
    // AES-CBC: 16-byte IV in front, PKCS#5 padding at the end
    if (data.length < 32) return new Uint8Array(0);
    const out = aesCbc(key, data.subarray(0, 16), data, 16, true);
    const padN = out.length > 0 ? out[out.length - 1] : 0;
    return padN >= 1 && padN <= 16 && padN <= out.length ? out.subarray(0, out.length - padN) : out;
  }

  private decryptAllStrings(): void {
    // strings of top-level objects (not inside object streams, not the encryption dictionary)
    const c = this.crypt;
    if (!c || c.strF === "none") return;
    let count = 0;
    for (const [num, e] of Array.from(this.objs.entries())) {
      if ((++count & 1023) === 0 && Date.now() > runDeadline) { this.flagIncomplete("time budget exhausted"); break; }
      if (num === c.encNum) continue;
      let top: PObj = e.obj;
      if (isStream(top)) {
        const ty = top.d.m.get("Type");
        if (ty !== undefined && isName(ty) && ty.v === "XRef") continue;
        top = top.d;
      }
      if (isDict(top)) {
        const ty = top.m.get("Type");
        if (ty !== undefined && isName(ty) && ty.v === "Sig") continue;
      }
      const stack: PObj[] = [top];
      let guard = 0;
      while (stack.length > 0 && ++guard < 200000) {
        const o = stack.pop();
        if (o === undefined || o === null || typeof o !== "object") continue;
        if (o.t === "str") {
          const b = this.decryptBytes(latin1ToBytes(o.v), num, e.gen, c.strF);
          o.v = bytesToLatin1(b, 0, b.length);
        } else if (o.t === "arr") {
          for (const x of o.v) stack.push(x);
        } else if (o.t === "dict") {
          for (const x of Array.from(o.m.values())) stack.push(x);
        }
      }
    }
  }

  private expandObjectStreams(): void {
    const stms: { entry: ObjEntry; num: number }[] = [];
    for (const [num, e] of Array.from(this.objs.entries())) {
      if (isStream(e.obj)) {
        const ty = e.obj.d.m.get("Type");
        if (ty !== undefined && isName(ty) && ty.v === "ObjStm") stms.push({ entry: e, num: num });
      }
    }
    stms.sort((a, b) => a.entry.pos - b.entry.pos);
    for (const st of stms) {
      try {
        const stream = st.entry.obj as PStream;
        const data = this.streamData(stream);
        const text = bytesToLatin1(data, 0, data.length);
        const n = this.num(stream.d.m.get("N"), 0);
        const first = this.num(stream.d.m.get("First"), 0);
        const hdr = new Lexer(text, 0);
        const pairs: number[] = [];
        for (let i = 0; i < n * 2; i++) {
          const v = hdr.parse(0);
          if (!isNum(v)) break;
          pairs.push(v);
        }
        for (let i = 0; i + 1 < pairs.length; i += 2) {
          const onum = pairs[i], off = pairs[i + 1];
          const lx = new Lexer(text, first + off);
          const obj = lx.parse(0);
          const existing = this.objs.get(onum);
          const def: ObjEntry = { obj: obj === null || isKw(obj) ? null : obj, pos: st.entry.pos, gen: 0 };
          // position rule: the definition that appears later in the file wins
          if (existing === undefined || existing.pos < st.entry.pos) {
            if (existing !== undefined) this.remember(onum, existing);
            this.objs.set(onum, def);
          } else this.remember(onum, def);
        }
      } catch (e) {
        this.warnings.push("ObjStm " + st.num + ": " + String(e));
      }
    }
  }

  private remember(num: number, e: ObjEntry): void {
    // keeps a replaced definition (needed to tell whether an update after signing changed an object)
    const h = this.history.get(num);
    if (h === undefined) this.history.set(num, [e]);
    else if (h.length < 64) h.push(e);
  }

  private hasEncryptedPayload(): boolean {
    // ISO 32000-2 unencrypted wrapper document: the real (encrypted) PDF is an embedded file with
    // /AFRelationship /EncryptedPayload; the visible page is only a cover sheet
    for (const e of Array.from(this.objs.values())) {
      const d = isDict(e.obj) ? e.obj : isStream(e.obj) ? e.obj.d : null;
      if (d === null) continue;
      const af = d.m.get("AFRelationship"), ty = d.m.get("Type"), ep = d.m.get("EP");
      if (af !== undefined && isName(af) && af.v === "EncryptedPayload") return true;
      if (ty !== undefined && isName(ty) && ty.v === "EncryptedPayload") return true;
      if (ep !== undefined && isDict(ep)) {
        const et = ep.m.get("Type");
        if (et !== undefined && isName(et) && et.v === "EncryptedPayload") return true;
      }
    }
    return false;
  }

  changedAfterSigning(): string {
    // A signed PDF with an incremental update after its last signature: names the first object used by the
    // pages (page tree, content streams, resources, annotations and their appearances) that this update added
    // or changed, "" when there is none. Updates that only add LTV data (DSS) or touch the catalog pass.
    const s = this.s;
    let sigEnd = -1;
    let p = s.indexOf("/ByteRange");
    for (let k = 0; p >= 0 && k < 500; k++) {
      let arr: PObj | null = null;
      try { arr = new Lexer(s, p + 10).parse(0); } catch (e) { arr = null; }
      if (arr !== null && isArr(arr) && arr.v.length === 4) {
        const a = arr.v[0], b = arr.v[1], c = arr.v[2], d = arr.v[3];
        // a real signature: [0 b c d] around the /Contents hex string, inside the file
        if (isNum(a) && isNum(b) && isNum(c) && isNum(d) && a === 0 && b > 0 && c > b && d >= 0 && c + d <= s.length &&
          s.charCodeAt(b) === 60 && s.charCodeAt(c - 1) === 62 && c + d > sigEnd) sigEnd = c + d;
      }
      p = s.indexOf("/ByteRange", p + 10);
    }
    if (sigEnd < 0) return "";
    let q = sigEnd;
    while (q < s.length && q < sigEnd + 256 && s.charCodeAt(q) <= 32) q++;
    if (q >= s.length) return "";
    const cat = this.catalog();
    const pagesRef = cat ? cat.m.get("Pages") : undefined;
    if (pagesRef === undefined) return "";
    const stack: PObj[] = [pagesRef];
    const seen = new Set<number>();
    for (let guard = 0; stack.length > 0 && guard < 200000; guard++) {
      const o = stack.pop();
      if (o === undefined || o === null || typeof o !== "object") continue;
      if (o.t === "ref") {
        if (seen.has(o.n) || seen.size > 20000) continue;
        seen.add(o.n);
        const e = this.objs.get(o.n);
        if (e === undefined) continue;
        if (e.pos >= sigEnd) {
          let old: ObjEntry | null = null;
          const hist = this.history.get(o.n);
          if (hist !== undefined) for (const h of hist) if (h.pos < sigEnd && (old === null || h.pos > old.pos)) old = h;
          if (old === null || !samePdfObj(old.obj, e.obj, 0)) return "object " + o.n + (old === null ? " added" : " changed");
        }
        stack.push(e.obj);
        continue;
      }
      if (o.t === "arr") { for (const x of o.v) stack.push(x); continue; }
      const d = o.t === "dict" ? o : o.t === "stream" ? o.d : null;
      if (d === null || d.m.has("ByteRange")) continue; // a signature value is covered by its own signature
      const ty = d.m.get("Type");
      const node = ty !== undefined && isName(ty) && (ty.v === "Page" || ty.v === "Pages");
      for (const [key, val] of Array.from(d.m.entries())) {
        if (key === "Parent" ? !node : SIGN_SKIP_KEYS.indexOf(key) >= 0) continue;
        stack.push(val);
      }
    }
    return "";
  }

  private loadOptionalContent(): void {
    // optional-content groups that are OFF in the default configuration (/OCProperties /D)
    const cat = this.catalog();
    const ocp = cat ? this.dictOf(cat.m.get("OCProperties")) : null;
    if (!ocp) return;
    this.ocUsed = true;
    const d = this.dictOf(ocp.m.get("D"));
    if (!d) return;
    if (this.nameOf(d.m.get("BaseState")) === "OFF") {
      for (const g of this.arrOf(ocp.m.get("OCGs"))) { const gd = this.dictOf(g); if (gd) this.ocOff.add(gd); }
      for (const g of this.arrOf(d.m.get("ON"))) { const gd = this.dictOf(g); if (gd) this.ocOff.delete(gd); }
    }
    for (const g of this.arrOf(d.m.get("OFF"))) { const gd = this.dictOf(g); if (gd) this.ocOff.add(gd); }
  }

  isHiddenOC(o: PObj | undefined): boolean {
    // true when an optional-content group or membership dictionary is OFF by default
    if (!this.ocUsed || o === undefined) return false;
    const d = this.dictOf(o);
    if (!d) return false;
    if (this.nameOf(d.m.get("Type")) !== "OCMD") return this.ocOff.has(d);
    const raw = this.resolve(d.m.get("OCGs"));
    const groups: PDict[] = [];
    if (isDict(raw)) groups.push(raw);
    else if (isArr(raw)) for (const g of raw.v) { const gd = this.dictOf(g); if (gd) groups.push(gd); }
    if (groups.length === 0) return false;
    let on = 0;
    for (const g of groups) if (!this.ocOff.has(g)) on++;
    const policy = this.nameOf(d.m.get("P"));
    if (policy === "AllOn") return on < groups.length;
    if (policy === "AnyOff") return on === groups.length;
    if (policy === "AllOff") return on > 0;
    return on === 0; // AnyOn (default)
  }

  producerInfo(): string {
    // /Producer and /Creator of the document information dictionary (NULs of UTF-16 removed)
    const info = this.dictOf(this.infoObj === null ? undefined : this.infoObj);
    if (!info) return "";
    let out = "";
    const keys = ["Producer", "Creator"];
    for (const k of keys) {
      const v = this.resolve(info.m.get(k));
      if (isStr(v)) out += " " + v.v.replace(/\u0000/g, "");
    }
    return out;
  }

  resolve(o: PObj | undefined): PObj {
    // object access
    let cur: PObj = o === undefined ? null : o;
    for (let i = 0; i < 32 && isRef(cur); i++) {
      const e = this.objs.get(cur.n);
      cur = e === undefined ? null : e.obj;
    }
    return isRef(cur) ? null : cur;
  }
  get(d: PDict | null, key: string): PObj {
    if (!d) return null;
    return this.resolve(d.m.get(key));
  }
  num(o: PObj | undefined, def: number): number {
    const r = this.resolve(o);
    return isNum(r) ? r : def;
  }
  nameOf(o: PObj | undefined): string {
    const r = this.resolve(o);
    return isName(r) ? r.v : "";
  }
  dictOf(o: PObj | undefined): PDict | null {
    const r = this.resolve(o);
    if (isDict(r)) return r;
    if (isStream(r)) return r.d;
    return null;
  }
  arrOf(o: PObj | undefined): PObj[] {
    const r = this.resolve(o);
    return isArr(r) ? r.v : [];
  }
  numArr(o: PObj | undefined, def: number): number[] {
    // numbers of an array object (plain loop, no Array callback)
    const out: number[] = [];
    for (const v of this.arrOf(o)) out.push(this.num(v, def));
    return out;
  }

  streamData(st: PStream): Uint8Array {
    // stream decoding
    const cached = this.streamCache.get(st.id);
    if (cached !== undefined) return cached;
    if (this.failedStreams.has(st.id)) throw new Error("stream could not be decoded (see its first warning)");
    if (Date.now() > runDeadline) {
      this.flagIncomplete("time budget exhausted");
      throw new Error("time budget exhausted");
    }
    this.failedStreams.add(st.id); // removed again below on success: a broken or oversized stream is decoded only once
    let data = latin1ToBytes(st.exactLen ? st.raw : this.refineRaw(st));
    const filters: string[] = [];
    const f = this.resolve(st.d.m.get("Filter"));
    if (isName(f)) filters.push(f.v);
    else if (isArr(f)) for (const x of f.v) { const n = this.resolve(x); if (isName(n)) filters.push(n.v); }
    const parmsObj = this.resolve(st.d.m.get("DecodeParms"));
    const parms: (PDict | null)[] = [];
    if (isDict(parmsObj)) parms.push(parmsObj);
    else if (isArr(parmsObj)) for (const x of parmsObj.v) { const d = this.resolve(x); parms.push(isDict(d) ? d : null); }
    if (this.crypt) {
      let method = this.crypt.stmF;
      const ty = this.nameOf(st.d.m.get("Type"));
      if (filters.length > 0 && filters[0] === "Crypt") {
        const cp = parms.length > 0 ? parms[0] : null;
        const cn = cp ? this.nameOf(cp.m.get("Name")) : "";
        const cm = this.crypt.filters.get(cn || "Identity");
        method = cm === undefined || cm.charAt(0) === "?" ? "none" : cm;
      } else if (ty === "XRef" || (ty === "Metadata" && !this.crypt.encryptMetadata)) {
        method = "none";
      }
      if (method !== "none") data = this.decryptBytes(data, st.n, st.g, method);
    }
    for (let i = 0; i < filters.length; i++) {
      const name = filters[i];
      const pd = parms.length === 1 && filters.length === 1 ? parms[0] : (parms[i] || null);
      if (name === "FlateDecode" || name === "Fl") {
        const r = inflate(data);
        if (!r.complete) this.flagIncomplete("compressed stream " + st.n + " is truncated or corrupt");
        data = this.predict(r.data, pd);
      } else if (name === "LZWDecode" || name === "LZW") {
        const r = lzwDecode(data, this.num(pd ? pd.m.get("EarlyChange") : undefined, 1));
        if (!r.complete) this.flagIncomplete("LZW stream " + st.n + " is truncated or corrupt");
        data = this.predict(r.data, pd);
      } else if (name === "ASCIIHexDecode" || name === "AHx") {
        data = asciiHexDecode(data);
      } else if (name === "ASCII85Decode" || name === "A85") {
        data = ascii85Decode(data);
      } else if (name === "RunLengthDecode" || name === "RL") {
        data = runLengthDecode(data);
      } else if (name === "Crypt") {
        // crypt filter: already applied above
      } else {
        // image / unsupported filters: leave as is
        break;
      }
    }
    this.failedStreams.delete(st.id);
    this.streamCache.set(st.id, data);
    return data;
  }
  private refineRaw(st: PStream): string {
    // stream cut at "endstream": an indirect /Length that ends right before "endstream" is exact
    const len = this.num(st.d.m.get("Length"), -1);
    const s = this.s;
    if (len >= 0 && st.start + len <= s.length) {
      const probe = new Lexer(s, st.start + len);
      probe.skipWs();
      if (s.substring(probe.pos, probe.pos + 9) === "endstream") return s.substring(st.start, st.start + len);
    }
    return st.raw;
  }
  private predict(data: Uint8Array, pd: PDict | null): Uint8Array {
    if (!pd) return data;
    const pred = this.num(pd.m.get("Predictor"), 1);
    if (pred <= 1) return data;
    return applyPredictor(data, pred, this.num(pd.m.get("Colors"), 1), this.num(pd.m.get("BitsPerComponent"), 8), this.num(pd.m.get("Columns"), 1));
  }
  streamText(st: PStream): string {
    const d = this.streamData(st);
    return bytesToLatin1(d, 0, d.length);
  }

  catalog(): PDict | null {
    let root: PDict | null = this.trailerRoot ? this.dictOf(this.trailerRoot) : null;
    if (!root) root = this.findCatalog();
    return root;
  }

  pages(): PageRef[] {
    // page tree
    const out: PageRef[] = [];
    const seen = new Set<PDict>();
    const root = this.catalog();
    const pagesRoot = root ? this.dictOf(root.m.get("Pages")) : null;
    if (pagesRoot) this.walkPages(pagesRoot, null, 0, out, seen);
    if (out.length === 0) {
      // fallback: every /Type /Page object in file order
      const found: { d: PDict; pos: number }[] = [];
      for (const e of Array.from(this.objs.values())) {
        if (isDict(e.obj) && this.nameOf(e.obj.m.get("Type")) === "Page") found.push({ d: e.obj, pos: e.pos });
      }
      found.sort((a, b) => a.pos - b.pos);
      for (const f of found) {
        let res = this.dictOf(f.d.m.get("Resources"));
        let parent = this.dictOf(f.d.m.get("Parent"));
        for (let i = 0; !res && parent && i < 32; i++) {
          res = this.dictOf(parent.m.get("Resources"));
          parent = this.dictOf(parent.m.get("Parent"));
        }
        out.push({ dict: f.d, resources: res, box: this.pageBox(f.d) });
      }
    }
    return out;
  }

  private walkPages(node: PDict, inherited: PDict | null, depth: number, out: PageRef[], seen: Set<PDict>): void {
    if (depth > 64 || seen.has(node)) return;
    seen.add(node);
    const res = this.dictOf(node.m.get("Resources")) || inherited;
    const type = this.nameOf(node.m.get("Type"));
    const kids = this.arrOf(node.m.get("Kids"));
    if (type === "Page" || (kids.length === 0 && node.m.has("Contents"))) {
      out.push({ dict: node, resources: res, box: this.pageBox(node) });
      return;
    }
    for (const k of kids) {
      const kd = this.dictOf(k);
      if (kd) this.walkPages(kd, res, depth + 1, out, seen);
      else if (isRef(k)) this.flagIncomplete("page object " + k.n + " missing");
    }
  }

  private pageBox(page: PDict): number[] {
    // visible area: CropBox, else MediaBox (both inheritable), as [x0, y0, x1, y1]
    let node: PDict | null = page;
    let media: number[] = [], crop: number[] = [];
    for (let i = 0; node && i < 32; i++) {
      if (crop.length !== 4) crop = this.numArr(node.m.get("CropBox"), 0);
      if (media.length !== 4) media = this.numArr(node.m.get("MediaBox"), 0);
      node = this.dictOf(node.m.get("Parent"));
    }
    const b = crop.length === 4 ? crop : media.length === 4 ? media : [0, 0, 612, 792];
    return [Math.min(b[0], b[2]), Math.min(b[1], b[3]), Math.max(b[0], b[2]), Math.max(b[1], b[3])];
  }

  private findCatalog(): PDict | null {
    let found: PDict | null = null;
    for (const e of Array.from(this.objs.values())) {
      if (found === null && isDict(e.obj) && this.nameOf(e.obj.m.get("Type")) === "Catalog") found = e.obj;
    }
    return found;
  }

  pageContent(page: PDict): string {
    const raw = page.m.get("Contents");
    const c = this.resolve(raw);
    if (isStream(c)) return this.streamText(c);
    if (isArr(c)) {
      let s = "";
      for (const x of c.v) {
        const st = this.resolve(x);
        if (isStream(st)) s += this.streamText(st) + "\n";
        else if (isRef(x)) this.flagIncomplete("content stream " + x.n + " missing");
      }
      return s;
    }
    if (raw !== undefined && isRef(raw)) this.flagIncomplete("content stream " + raw.n + " missing");
    return "";
  }
}

// ---------------------------------------------------------------------
// CMaps (ToUnicode + embedded encoding CMaps)
// ---------------------------------------------------------------------
interface CodeRange { nBytes: number; lo: number; hi: number }

interface CMapData {
  ranges: CodeRange[];
  single: Map<number, string>;             // code -> unicode (ToUnicode) or CID as string (encoding cmap)
  rangeList: { lo: number; hi: number; dst: number; nBytes: number }[]; // code ranges -> starting cid / code point
  vertical: boolean;
}

function hexStrToInt(s: string): number {
  let v = 0;
  for (let i = 0; i < s.length && i < 4; i++) v = (v << 8) | (s.charCodeAt(i) & 0xff);
  return v >>> 0;
}

function utf16beToString(s: string): string {
  if (s.length === 1) return s; // single byte destination
  let out = "";
  for (let i = 0; i + 1 < s.length; i += 2) {
    const cu = ((s.charCodeAt(i) & 0xff) << 8) | (s.charCodeAt(i + 1) & 0xff);
    out += String.fromCharCode(cu);
  }
  if (s.length % 2 === 1) out += String.fromCharCode(s.charCodeAt(s.length - 1) & 0xff);
  return out;
}

function stringIncrement(s: string, by: number): string {
  // increment the last UTF-16 code unit (sufficient for bfrange destinations)
  if (s.length === 0) return s;
  const last = s.charCodeAt(s.length - 1) + by;
  return s.substring(0, s.length - 1) + String.fromCharCode(last & 0xffff);
}

function parseCMap(text: string, mode: "uni" | "cid"): CMapData {
  // mode "uni": destinations are UTF-16BE strings; mode "cid": destinations are integers
  const cm: CMapData = { ranges: [], single: new Map<number, string>(), rangeList: [], vertical: false };
  const lx = new Lexer(text, 0);
  const stack: PObj[] = [];
  let guard = 0;
  // one try for the whole CMap (each executed try costs milliseconds in Office Scripts): a token that cannot be
  // read ends the CMap as before, other exceptions propagate
  let reading = false;
  try {
    for (;;) {
      if (++guard > 2000000) break;
      reading = true;
      const o = lx.parse(0);
      reading = false;
      if (o === null) { if (lx.pos >= text.length) break; continue; }
      if (!isKw(o)) { stack.push(o); if (stack.length > 64) stack.shift(); continue; }
      const kw = o.v;
      if (kw === "begincodespacerange") {
        for (;;) {
          const a = lx.parse(0); if (a === null || isKw(a)) break;
          const b = lx.parse(0); if (b === null || isKw(b)) break;
          if (isStr(a) && isStr(b)) cm.ranges.push({ nBytes: Math.max(1, Math.min(4, a.v.length)), lo: hexStrToInt(a.v), hi: hexStrToInt(b.v) });
        }
      } else if (kw === "beginbfchar" || kw === "begincidchar") {
        for (;;) {
          const a = lx.parse(0); if (a === null || isKw(a)) break;
          const b = lx.parse(0); if (b === null || isKw(b)) break;
          if (!isStr(a)) continue;
          const code = hexStrToInt(a.v);
          if (mode === "uni") {
            if (isStr(b)) cm.single.set(code, utf16beToString(b.v));
            else if (isName(b)) { const u = glyphNameToUnicode(b.v); if (u) cm.single.set(code, u); }
          } else if (isNum(b)) cm.single.set(code, String(b));
        }
      } else if (kw === "beginbfrange" || kw === "begincidrange") {
        for (;;) {
          const a = lx.parse(0); if (a === null || isKw(a)) break;
          const b = lx.parse(0); if (b === null || isKw(b)) break;
          const c = lx.parse(0); if (c === null || isKw(c)) break;
          if (!isStr(a) || !isStr(b)) continue;
          const lo = hexStrToInt(a.v), hi = hexStrToInt(b.v);
          if (hi < lo || hi - lo > 65535) continue;
          if (mode === "uni") {
            if (isStr(c)) {
              const dst = utf16beToString(c.v);
              if (dst.length === 1) cm.rangeList.push({ lo: lo, hi: hi, dst: dst.charCodeAt(0), nBytes: a.v.length });
              else for (let k = 0; k <= hi - lo; k++) cm.single.set(lo + k, stringIncrement(dst, k));
            } else if (isArr(c)) {
              for (let k = 0; k < c.v.length && lo + k <= hi; k++) {
                const d = c.v[k];
                if (isStr(d)) cm.single.set(lo + k, utf16beToString(d.v));
              }
            }
          } else if (isNum(c)) {
            cm.rangeList.push({ lo: lo, hi: hi, dst: c, nBytes: a.v.length });
          }
        }
      } else if (kw === "endcmap") {
        // keep going; some files concatenate
      } else if (kw === "def") {
        // /WMode 1 def
        if (stack.length >= 2 && isName(stack[stack.length - 2]) && (stack[stack.length - 2] as PName).v === "WMode" && stack[stack.length - 1] === 1) cm.vertical = true;
      }
    }
  } catch (e) {
    if (!reading) throw e;
  }
  return cm;
}

function cmapLookup(cm: CMapData, code: number): string | null {
  const s = cm.single.get(code);
  if (s !== undefined) return s;
  for (let i = cm.rangeList.length - 1; i >= 0; i--) {
    const r = cm.rangeList[i];
    if (code >= r.lo && code <= r.hi) return String.fromCharCode(r.dst + (code - r.lo));
  }
  return null;
}
function cmapLookupCid(cm: CMapData, code: number): number {
  const s = cm.single.get(code);
  if (s !== undefined) return parseInt(s, 10);
  for (let i = cm.rangeList.length - 1; i >= 0; i--) {
    const r = cm.rangeList[i];
    if (code >= r.lo && code <= r.hi) return r.dst + (code - r.lo);
  }
  return code;
}

function glyphNameToUnicode(name: string): string {
  // Glyph names -> Unicode
  if (name.length === 0) return "";
  const direct = GLYPHS[name];
  if (direct !== undefined) return String.fromCharCode(direct);
  const dot = name.indexOf(".");
  if (dot > 0) return glyphNameToUnicode(name.substring(0, dot));
  let m = /^uni([0-9A-Fa-f]{4})/.exec(name);
  if (m) return String.fromCharCode(parseInt(m[1], 16));
  m = /^u([0-9A-Fa-f]{4,6})$/.exec(name);
  if (m) {
    const cp = parseInt(m[1], 16);
    if (cp <= 0xffff) return String.fromCharCode(cp);
    const v = cp - 0x10000;
    return String.fromCharCode(0xd800 + (v >> 10), 0xdc00 + (v & 0x3ff));
  }
  m = /^(?:g|cid|c|G|index)(\d+)$/.exec(name);
  if (m) return ""; // glyph index names carry no Unicode
  if (name.length === 1) return name;
  // names like "Cxx" / "Gxx" / "ccxx" are unknown
  return "";
}

// ---------------------------------------------------------------------
// TrueType 'cmap' parsing (for fonts without ToUnicode)
// ---------------------------------------------------------------------
interface TtMaps { gidToUni: Map<number, number>; codeToGid: Map<number, number>; hasUni: boolean }

function parseTrueTypeCmap(data: Uint8Array): TtMaps | null {
  const u16 = (p: number): number => (data[p] << 8) | data[p + 1];
  const u32 = (p: number): number => ((data[p] << 24) | (data[p + 1] << 16) | (data[p + 2] << 8) | data[p + 3]) >>> 0;
  if (data.length < 12) return null;
  let base = 0;
  const tag = u32(0);
  if (tag === 0x74746366) base = u32(12); // 'ttcf' collection: first font
  const numTables = u16(base + 4);
  if (numTables > 512) return null;
  let cmapOff = -1, cmapLen = 0;
  for (let i = 0; i < numTables; i++) {
    const rec = base + 12 + i * 16;
    if (rec + 16 > data.length) break;
    const t = bytesToLatin1(data, rec, rec + 4);
    if (t === "cmap") { cmapOff = u32(rec + 8); cmapLen = u32(rec + 12); }
  }
  if (cmapOff < 0 || cmapOff + 4 > data.length || cmapLen < 4) return null;
  const maps: TtMaps = { gidToUni: new Map<number, number>(), codeToGid: new Map<number, number>(), hasUni: false };
  const n = u16(cmapOff + 2);
  // (code, glyph) pairs of one subtable, stored in the loop body below (no local helper: keeps the
  // "first code point wins" order intact when the runtime makes helpers async)
  const pc: number[] = [], pg: number[] = [];
  for (let i = 0; i < n && i < 32; i++) {
    const rec = cmapOff + 4 + i * 8;
    if (rec + 8 > data.length) break;
    const pid = u16(rec), eid = u16(rec + 2), off = u32(rec + 4);
    const sub = cmapOff + off;
    if (sub + 4 > data.length) continue;
    const isUni = (pid === 3 && (eid === 1 || eid === 10)) || pid === 0;
    const isSym = pid === 3 && eid === 0;
    const isMac = pid === 1 && eid === 0;
    if (!isUni && !isSym && !isMac) continue;
    const format = u16(sub);
    pc.length = 0;
    pg.length = 0;
    if (format === 0) {
      for (let c = 0; c < 256; c++) { pc.push(c); pg.push(data[sub + 6 + c]); }
    } else if (format === 4) {
      const segX2 = u16(sub + 6);
      const endP = sub + 14, startP = endP + segX2 + 2, deltaP = startP + segX2, rangeP = deltaP + segX2;
      for (let s = 0; s < segX2 / 2; s++) {
        const end = u16(endP + s * 2), start = u16(startP + s * 2), delta = u16(deltaP + s * 2), ro = u16(rangeP + s * 2);
        if (start > end) continue;
        for (let c = start; c <= end && c !== 0xffff; c++) {
          let gid: number;
          if (ro === 0) gid = (c + delta) & 0xffff;
          else {
            const gp = rangeP + s * 2 + ro + (c - start) * 2;
            if (gp + 2 > data.length) continue;
            gid = u16(gp);
            if (gid !== 0) gid = (gid + delta) & 0xffff;
          }
          pc.push(c);
          pg.push(gid);
        }
      }
    } else if (format === 6) {
      const first = u16(sub + 6), cnt = u16(sub + 8);
      for (let k = 0; k < cnt; k++) { pc.push(first + k); pg.push(u16(sub + 10 + k * 2)); }
    } else if (format === 12) {
      const nGroups = u32(sub + 12);
      for (let g = 0; g < nGroups && g < 100000 && pc.length < 300000; g++) {
        const gp = sub + 16 + g * 12;
        if (gp + 12 > data.length) break;
        const sc = u32(gp), ec = u32(gp + 4), sg = u32(gp + 8);
        for (let c = sc; c <= ec && c - sc < 65536; c++) { pc.push(c); pg.push(sg + (c - sc)); }
      }
    }
    for (let q = 0; q < pc.length; q++) {
      const code = pc[q], gid = pg[q];
      if (isUni) {
        maps.hasUni = true;
        if (gid !== 0 && !maps.gidToUni.has(gid)) maps.gidToUni.set(gid, code);
      } else if (isSym) { if (!maps.codeToGid.has(code & 0xff)) maps.codeToGid.set(code & 0xff, gid); }
      else if (isMac) { if (!maps.codeToGid.has(code)) maps.codeToGid.set(code, gid); }
    }
  }
  return maps;
}

// ---------------------------------------------------------------------
// Fonts
// ---------------------------------------------------------------------
interface FontInfo {
  composite: boolean;
  ranges: CodeRange[];
  toUni: CMapData | null;        // ToUnicode
  encCMap: CMapData | null;      // composite: embedded encoding CMap (code -> CID); null = Identity
  simple: string[];              // simple fonts: code -> unicode ("" unknown)
  widths: Map<number, number>;   // simple: by code; composite: by CID
  defaultWidth: number;
  stdWidths: number[] | null;    // standard-14 fallback (index code-32)
  type3: boolean;
  fontMatrix: number[];
  tt: TtMaps | null;             // embedded TrueType cmap (fallback mapping)
  cidToGid: Uint8Array | null;   // CIDToGIDMap stream (uint16 BE), null = identity
  spaceWidth: number;
  ocrFont: boolean;              // font name typical for OCR text layers (Tesseract "GlyphLessFont")
}

interface Glyph { code: number; u: string; w: number; isSpace: boolean }

class FontLoader {
  doc: PdfDoc;
  cache: Map<PDict, FontInfo>;
  fallbackFont: FontInfo | null;
  constructor(doc: PdfDoc) {
    this.doc = doc;
    this.cache = new Map<PDict, FontInfo>();
    this.fallbackFont = null;
  }

  load(fontObj: PObj | undefined): FontInfo | null {
    const d = this.doc.dictOf(fontObj);
    if (!d) return null;
    const hit = this.cache.get(d);
    if (hit !== undefined) return hit;
    let f: FontInfo;
    try { f = this.build(d); } catch (e) { this.doc.warnings.push("font: " + String(e)); f = this.build(mkDict()); }
    this.cache.set(d, f);
    return f;
  }

  fallback(): FontInfo {
    // Helvetica/WinAnsi stand-in for missing font resources
    if (!this.fallbackFont) {
      const d = mkDict();
      d.m.set("BaseFont", mkName("Helvetica"));
      d.m.set("Subtype", mkName("Type1"));
      d.m.set("Encoding", mkName("WinAnsiEncoding"));
      this.fallbackFont = this.build(d);
    }
    return this.fallbackFont;
  }

  private build(d: PDict): FontInfo {
    const doc = this.doc;
    const subtype = doc.nameOf(d.m.get("Subtype"));
    const f: FontInfo = {
      composite: subtype === "Type0",
      ranges: [],
      toUni: null,
      encCMap: null,
      simple: [],
      widths: new Map<number, number>(),
      defaultWidth: 0,
      stdWidths: null,
      type3: subtype === "Type3",
      fontMatrix: [0.001, 0, 0, 0.001, 0, 0],
      tt: null,
      cidToGid: null,
      spaceWidth: 250,
      ocrFont: /GlyphLess/i.test(doc.nameOf(d.m.get("BaseFont"))),
    };
    // ToUnicode
    const tu = doc.resolve(d.m.get("ToUnicode"));
    if (isStream(tu)) {
      try { f.toUni = parseCMap(doc.streamText(tu), "uni"); } catch (e) { doc.warnings.push("ToUnicode: " + String(e)); }
    }
    let descriptor: PDict | null = null;
    if (f.composite) {
      const desc = doc.arrOf(d.m.get("DescendantFonts"));
      const cid = desc.length > 0 ? doc.dictOf(desc[0]) : null;
      descriptor = cid ? doc.dictOf(cid.m.get("FontDescriptor")) : null;
      const enc = doc.resolve(d.m.get("Encoding"));
      if (isStream(enc)) {
        try { f.encCMap = parseCMap(doc.streamText(enc), "cid"); } catch (e) { /* ignore */ }
        if (f.encCMap && f.encCMap.ranges.length > 0) f.ranges = f.encCMap.ranges.slice(0);
      } else if (isName(enc) && enc.v.indexOf("Identity") !== 0) {
        // predefined (CJK) CMaps are not embedded; we can only use ToUnicode
        if (enc.v.indexOf("UCS2") >= 0 || enc.v.indexOf("UTF16") >= 0) f.ranges = [{ nBytes: 2, lo: 0, hi: 0xffff }];
      }
      // Identity-H/V codes are always 2 bytes, whatever codespace the ToUnicode CMap declares (R6)
      if (isName(enc) && enc.v.indexOf("Identity") === 0) f.ranges = [{ nBytes: 2, lo: 0, hi: 0xffff }];
      if (f.ranges.length === 0 && f.toUni && f.toUni.ranges.length > 0) f.ranges = f.toUni.ranges.slice(0);
      if (f.ranges.length === 0) f.ranges = [{ nBytes: 2, lo: 0, hi: 0xffff }];
      f.defaultWidth = cid ? doc.num(cid.m.get("DW"), 1000) : 1000;
      if (cid) this.parseW(doc.arrOf(cid.m.get("W")), f.widths);
      const c2g = cid ? doc.resolve(cid.m.get("CIDToGIDMap")) : null;
      if (isStream(c2g)) f.cidToGid = doc.streamData(c2g);
      // embedded TrueType program for the fallback mapping
      const ff = descriptor ? doc.resolve(descriptor.m.get("FontFile2")) : null;
      const ff3 = descriptor ? doc.resolve(descriptor.m.get("FontFile3")) : null;
      const prog = isStream(ff) ? ff : isStream(ff3) ? ff3 : null;
      if (prog && (!f.toUni || f.toUni.single.size + f.toUni.rangeList.length === 0)) {
        try { f.tt = parseTrueTypeCmap(doc.streamData(prog)); } catch (e) { /* ignore */ }
      }
      f.spaceWidth = this.cidWidth(f, 32) || 250;
    } else {
      descriptor = doc.dictOf(d.m.get("FontDescriptor"));
      const flags = descriptor ? doc.num(descriptor.m.get("Flags"), 0) : 0;
      const symbolic = (flags & 4) !== 0 && (flags & 32) === 0;
      const baseFont = doc.nameOf(d.m.get("BaseFont"));
      // base encoding
      let base: number[] = subtype === "TrueType" ? ENC_WINANSI : ENC_STANDARD;
      if (symbolic && subtype === "TrueType") base = ENC_WINANSI;
      const enc = doc.resolve(d.m.get("Encoding"));
      let encName = "";
      let diffs: PObj[] = [];
      if (isName(enc)) encName = enc.v;
      else if (isDict(enc)) { encName = doc.nameOf(enc.m.get("BaseEncoding")); diffs = doc.arrOf(enc.m.get("Differences")); }
      if (encName === "WinAnsiEncoding") base = ENC_WINANSI;
      else if (encName === "MacRomanEncoding") base = ENC_MACROMAN;
      else if (encName === "StandardEncoding" || encName === "MacExpertEncoding") base = ENC_STANDARD;
      for (let c = 0; c < 256; c++) f.simple.push(base[c] ? String.fromCharCode(base[c]) : "");
      if (f.type3) for (let c = 0; c < 256; c++) f.simple[c] = "";
      let code = 0;
      for (const x of diffs) {
        const r = doc.resolve(x);
        if (isNum(r)) code = r | 0;
        else if (isName(r)) { if (code >= 0 && code < 256) f.simple[code] = glyphNameToUnicode(r.v); code++; }
      }
      // embedded TrueType cmap for symbolic fonts without usable encoding
      if (subtype === "TrueType" && descriptor && !isDict(enc) && (!f.toUni || f.toUni.single.size + f.toUni.rangeList.length === 0)) {
        const ff = doc.resolve(descriptor.m.get("FontFile2"));
        if (isStream(ff)) { try { f.tt = parseTrueTypeCmap(doc.streamData(ff)); } catch (e) { /* ignore */ } }
      }
      // widths
      if (f.type3) {
        const fm = doc.numArr(d.m.get("FontMatrix"), 0);
        if (fm.length === 6) f.fontMatrix = fm;
      }
      const firstChar = doc.num(d.m.get("FirstChar"), 0);
      const widths = doc.arrOf(d.m.get("Widths"));
      for (let i = 0; i < widths.length; i++) {
        const w = doc.num(widths[i], -1);
        if (w >= 0) f.widths.set(firstChar + i, f.type3 ? w * f.fontMatrix[0] * 1000 : w);
      }
      f.defaultWidth = descriptor ? doc.num(descriptor.m.get("MissingWidth"), 0) : 0;
      if (widths.length === 0) {
        const bold = /bold|black|heavy|semibold/i.test(baseFont) || (descriptor ? doc.num(descriptor.m.get("FontWeight"), 400) >= 600 : false);
        if (/courier|mono/i.test(baseFont)) { f.stdWidths = null; f.defaultWidth = 600; }
        else if (/times|serif|georgia|garamond|book|roman/i.test(baseFont)) f.stdWidths = bold ? W_TIMESB : W_TIMES;
        else f.stdWidths = bold ? W_HELVB : W_HELV;
        if (!f.stdWidths && f.defaultWidth === 0) f.defaultWidth = 500;
      }
      f.spaceWidth = this.simpleWidth(f, 32) || 250;
    }
    return f;
  }

  private parseW(w: PObj[], out: Map<number, number>): void {
    const doc = this.doc;
    let i = 0;
    while (i < w.length) {
      const a = doc.resolve(w[i]);
      if (!isNum(a)) { i++; continue; }
      const b = doc.resolve(w[i + 1]);
      if (isArr(b)) {
        for (let k = 0; k < b.v.length; k++) out.set(a + k, doc.num(b.v[k], 1000));
        i += 2;
      } else if (isNum(b)) {
        const wv = doc.num(w[i + 2], 1000);
        if (b >= a && b - a < 65536) for (let c = a; c <= b; c++) out.set(c, wv);
        i += 3;
      } else i++;
    }
  }

  simpleWidth(f: FontInfo, code: number): number {
    const w = f.widths.get(code);
    if (w !== undefined) return w;
    if (f.stdWidths && code >= 32 && code < 256) {
      const sw = f.stdWidths[code - 32];
      if (sw > 0) return sw;
    }
    return f.defaultWidth > 0 ? f.defaultWidth : (f.stdWidths ? 500 : 0);
  }

  cidWidth(f: FontInfo, cid: number): number {
    const w = f.widths.get(cid);
    return w !== undefined ? w : f.defaultWidth;
  }

  decode(f: FontInfo, s: string): Glyph[] {
    // Splits a PDF string into glyphs (code, unicode, width/1000).
    const out: Glyph[] = [];
    if (!f.composite) {
      for (let i = 0; i < s.length; i++) {
        const code = s.charCodeAt(i) & 0xff;
        let u: string | null = f.toUni ? cmapLookup(f.toUni, code) : null;
        if (u === null) {
          u = f.simple[code];
          if (u === "" && f.tt) {
            let gid = f.tt.codeToGid.get(code);
            if (gid === undefined) gid = f.tt.codeToGid.get(0xf000 | code);
            if (gid !== undefined) { const g = f.tt.gidToUni.get(gid); if (g !== undefined) u = g <= 0xffff ? String.fromCharCode(g) : String.fromCharCode(0xd800 + ((g - 0x10000) >> 10), 0xdc00 + ((g - 0x10000) & 0x3ff)); }
          }
          if (u === "" && code >= 32) u = ENC_WINANSI[code] ? String.fromCharCode(ENC_WINANSI[code]) : "";
        }
        out.push({ code: code, u: u, w: this.simpleWidth(f, code), isSpace: code === 32 });
      }
      return out;
    }
    // composite: segment by codespace ranges
    let i = 0;
    while (i < s.length) {
      let n = 0, code = 0;
      let matched = false;
      for (const r of f.ranges) {
        if (i + r.nBytes > s.length) continue;
        let v = 0;
        for (let k = 0; k < r.nBytes; k++) v = (v << 8) | (s.charCodeAt(i + k) & 0xff);
        v = v >>> 0;
        if (v >= r.lo && v <= r.hi) { n = r.nBytes; code = v; matched = true; break; }
      }
      if (!matched) {
        n = Math.min(f.ranges[0].nBytes, s.length - i);
        code = 0;
        for (let k = 0; k < n; k++) code = (code << 8) | (s.charCodeAt(i + k) & 0xff);
        code = code >>> 0;
      }
      i += n;
      const cid = f.encCMap ? cmapLookupCid(f.encCMap, code) : code;
      let u: string | null = f.toUni ? cmapLookup(f.toUni, code) : null;
      if (u === null && f.tt) {
        let gid = cid;
        if (f.cidToGid && cid * 2 + 1 < f.cidToGid.length) gid = (f.cidToGid[cid * 2] << 8) | f.cidToGid[cid * 2 + 1];
        const g = f.tt.gidToUni.get(gid);
        if (g !== undefined) u = g <= 0xffff ? String.fromCharCode(g) : String.fromCharCode(0xd800 + ((g - 0x10000) >> 10), 0xdc00 + ((g - 0x10000) & 0x3ff));
      }
      if (u === null) u = "";
      out.push({ code: code, u: u, w: this.cidWidth(f, cid), isSpace: n === 1 && code === 32 });
    }
    return out;
  }
}

// ---------------------------------------------------------------------
// Content stream interpreter -> positioned text items
// ---------------------------------------------------------------------
// flip: kept for compatibility, always false (item y is in y-up user space, see R4)
interface TextItem { x: number; y: number; w: number; h: number; s: string; sp: number; page: number; flip: boolean; rot: number }

type Mat = [number, number, number, number, number, number];

function matMul(m1: Mat, m2: Mat): Mat {
  return [
    m1[0] * m2[0] + m1[1] * m2[2],
    m1[0] * m2[1] + m1[1] * m2[3],
    m1[2] * m2[0] + m1[3] * m2[2],
    m1[2] * m2[1] + m1[3] * m2[3],
    m1[4] * m2[0] + m1[5] * m2[2] + m2[4],
    m1[4] * m2[1] + m1[5] * m2[3] + m2[5],
  ];
}

// tr: text render mode (3 and 7 = invisible); fa / sa: fill / stroke alpha (ExtGState ca / CA);
// mask / blend: an ExtGState soft mask or a non-normal blend mode is active
interface GState { ctm: Mat; font: FontInfo | null; size: number; charSp: number; wordSp: number; hscale: number; leading: number; rise: number; tr: number; fa: number; sa: number; mask: boolean; blend: boolean }

function copyGState(g: GState): GState {
  return { ctm: g.ctm, font: g.font, size: g.size, charSp: g.charSp, wordSp: g.wordSp, hscale: g.hscale, leading: g.leading, rise: g.rise, tr: g.tr, fa: g.fa, sa: g.sa, mask: g.mask, blend: g.blend };
}

function newGState(ctm: Mat): GState {
  return { ctm: ctm, font: null, size: 0, charSp: 0, wordSp: 0, hscale: 1, leading: 0, rise: 0, tr: 0, fa: 1, sa: 1, mask: false, blend: false };
}

function invisibleText(gs: GState): boolean {
  // text that paints nothing: render mode 3/7, or zero alpha for the parts the mode paints
  // (Apple's Vision OCR layer uses an ExtGState with /ca 0 instead of 3 Tr)
  const tr = gs.tr;
  if (tr === 3 || tr === 7) return true;
  const fill = tr === 0 || tr === 2 || tr === 4 || tr === 6, stroke = tr === 1 || tr === 2 || tr === 5 || tr === 6;
  return (!fill || gs.fa < 0.01) && (!stroke || gs.sa < 0.01);
}

// Extraction statistics: glyph counts for the OCR and Unicode checks.
// glyphsOcr: invisible (Tr 3/7) or OCR-font glyphs; glyphsCovered: visible glyphs later painted over
// by a page-filling opaque image ("text under image" OCR); glyphsOnImagePages: other visible glyphs
// on pages with a page-filling image; glyphsNoUni: glyphs without a Unicode mapping.
class ContentInterpreter {
  doc: PdfDoc;
  items: TextItem[];
  fonts: FontLoader;
  formDepth: number;
  ops: number;
  deadline: number;
  glyphsTotal: number;
  glyphsOcr: number;
  glyphsCovered: number;
  glyphsOnImagePages: number;
  glyphsNoUni: number;
  pageNative: number;
  pageArea: number;
  pageHasImage: boolean;
  pagesWithImage: number;
  ocHidden: number;
  box: number[];

  constructor(doc: PdfDoc) {
    this.doc = doc;
    this.items = [];
    this.fonts = new FontLoader(doc);
    this.formDepth = 0;
    this.ops = 0;
    this.deadline = runDeadline; // one budget for the whole run, set in main
    this.glyphsTotal = 0;
    this.glyphsOcr = 0;
    this.glyphsCovered = 0;
    this.glyphsOnImagePages = 0;
    this.glyphsNoUni = 0;
    this.pageNative = 0;
    this.pageArea = 0;
    this.pageHasImage = false;
    this.pagesWithImage = 0;
    this.ocHidden = 0;
    this.box = [];
  }

  beginPage(box: number[]): void {
    this.box = box;
    this.pageArea = Math.abs((box[2] - box[0]) * (box[3] - box[1]));
    this.pageNative = 0;
    this.pageHasImage = false;
    this.ocHidden = 0;
  }

  endPage(): void {
    if (this.pageHasImage) {
      this.glyphsOnImagePages += this.pageNative;
      this.pagesWithImage++;
    }
    this.pageNative = 0;
  }

  runPage(content: string, resources: PDict | null, page: number): void {
    this.run(content, resources, newGState([1, 0, 0, 1, 0, 0]), page, new Set<number>());
  }

  runAnnotations(pageDict: PDict, resources: PDict | null, page: number): void {
    // Text inside form-field / annotation appearance streams (filled AcroForms, stamps)
    const doc = this.doc;
    const annots = doc.arrOf(pageDict.m.get("Annots"));
    if (annots.length === 0) return;
    // one try for all annotations (each executed try costs milliseconds in Office Scripts); after a failed
    // appearance stream the loop resumes with the next annotation
    let ai = 0;
    let inRun = false;
    for (;;) {
      try {
        for (; ai < annots.length; ai++) {
          const a = annots[ai];
          const ad = doc.dictOf(a);
          if (!ad) continue;
          const sub = doc.nameOf(ad.m.get("Subtype"));
          if (sub === "Link" || sub === "Popup") continue;
          const flags = doc.num(ad.m.get("F"), 0);
          if (flags & 34) continue; // Hidden (2) or NoView (32)
          if (doc.isHiddenOC(ad.m.get("OC"))) continue;
          // signature fields (/FT /Sig on the widget or inherited from a parent field, or a signature value
          // with /ByteRange): the signature box is not document text and must not mix into the amount lines
          let ft = doc.nameOf(ad.m.get("FT"));
          let parent = doc.dictOf(ad.m.get("Parent"));
          for (let k = 0; ft === "" && parent && k < 16; k++) {
            ft = doc.nameOf(parent.m.get("FT"));
            parent = doc.dictOf(parent.m.get("Parent"));
          }
          if (ft === "Sig") continue;
          const sigValue = sub === "Widget" ? doc.dictOf(ad.m.get("V")) : null;
          if (sigValue && sigValue.m.has("ByteRange")) continue;
          const ap = doc.dictOf(ad.m.get("AP"));
          if (!ap) { if (sub === "Widget") this.fieldValue(ad, page); continue; }
          let n = doc.resolve(ap.m.get("N"));
          if (isDict(n)) { // appearance sub-dictionary keyed by state
            const as = doc.nameOf(ad.m.get("AS"));
            const pick: PObj | undefined = as !== "" ? n.m.get(as) : (n.m.size > 0 ? n.m.values().next().value : undefined);
            n = doc.resolve(pick);
          }
          if (!isStream(n)) { if (sub === "Widget") this.fieldValue(ad, page); continue; }
          if (doc.isHiddenOC(n.d.m.get("OC"))) continue;
          const rect = doc.numArr(ad.m.get("Rect"), 0);
          const bbox = doc.numArr(n.d.m.get("BBox"), 0);
          let ctm: Mat = [1, 0, 0, 1, 0, 0];
          const mtx = doc.numArr(n.d.m.get("Matrix"), 0);
          if (mtx.length === 6) ctm = [mtx[0], mtx[1], mtx[2], mtx[3], mtx[4], mtx[5]];
          if (rect.length === 4 && bbox.length === 4) {
            // map transformed BBox onto Rect (PDF 12.5.5 algorithm, simplified: translate + scale)
            const corners = [[bbox[0], bbox[1]], [bbox[2], bbox[1]], [bbox[2], bbox[3]], [bbox[0], bbox[3]]].map((c) => [ctm[0] * c[0] + ctm[2] * c[1] + ctm[4], ctm[1] * c[0] + ctm[3] * c[1] + ctm[5]]);
            const minX = Math.min(corners[0][0], corners[1][0], corners[2][0], corners[3][0]), maxX = Math.max(corners[0][0], corners[1][0], corners[2][0], corners[3][0]);
            const minY = Math.min(corners[0][1], corners[1][1], corners[2][1], corners[3][1]), maxY = Math.max(corners[0][1], corners[1][1], corners[2][1], corners[3][1]);
            const rx0 = Math.min(rect[0], rect[2]), ry0 = Math.min(rect[1], rect[3]), rx1 = Math.max(rect[0], rect[2]), ry1 = Math.max(rect[1], rect[3]);
            const sx = maxX - minX > 1e-6 ? (rx1 - rx0) / (maxX - minX) : 1, sy = maxY - minY > 1e-6 ? (ry1 - ry0) / (maxY - minY) : 1;
            ctm = matMul(ctm, [sx, 0, 0, sy, rx0 - minX * sx, ry0 - minY * sy]);
          }
          const res = doc.dictOf(n.d.m.get("Resources")) || resources;
          inRun = true;
          const before = this.items.length;
          this.run(doc.streamText(n), res, newGState(ctm), page, new Set<number>([n.id]));
          inRun = false;
          // an empty appearance of a filled field (the viewer draws the value anew, /NeedAppearances)
          if (sub === "Widget" && this.items.length === before) this.fieldValue(ad, page);
        }
        break;
      } catch (e) {
        if (!inRun) throw e;
        inRun = false;
        doc.warnings.push("annotation: " + String(e));
        ai++;
      }
    }
  }

  private fieldValue(ad: PDict, page: number): void {
    // the value of a filled text or choice field that has no appearance of it (a server filled /V and set
    // /NeedAppearances): a viewer draws it into the field box, so its text is placed there, left, centred or right as /Q
    // says, in the font size of /DA (inherited from the parent fields)
    const doc = this.doc;
    let d: PDict | null = ad;
    let v: PObj | undefined = undefined;
    let ft = "", da = "";
    let q = -1;
    for (let k = 0; d !== null && k < 16; k++) {
      if (v === undefined && d.m.has("V")) v = doc.resolve(d.m.get("V"));
      if (ft === "") ft = doc.nameOf(d.m.get("FT"));
      const dv = doc.resolve(d.m.get("DA"));
      if (da === "" && isStr(dv)) da = dv.v;
      if (q < 0 && d.m.has("Q")) q = doc.num(d.m.get("Q"), 0);
      d = doc.dictOf(d.m.get("Parent"));
    }
    if ((ft !== "Tx" && ft !== "Ch") || v === undefined) return;
    const parts: string[] = [];
    if (isStr(v)) parts.push(v.v);
    else if (isArr(v)) for (const x of v.v) if (isStr(x) && parts.length < 20) parts.push(x.v);
    const texts: string[] = [];
    for (const x of parts) texts.push(pdfTextString(x));
    let s = texts.join(", ").replace(/[\r\n\t]+/g, " ").trim();
    // (a value exported as a bare number drops the trailing zero of its cents, "12126.1" for 12,126.10: a decimal amount)
    if (/^-?\d{1,12}[.,]\d$/.test(s)) s = s + "0";
    const rect = doc.numArr(ad.m.get("Rect"), 0);
    if (s === "" || rect.length !== 4) return;
    const x0 = Math.min(rect[0], rect[2]), x1 = Math.max(rect[0], rect[2]);
    const y0 = Math.min(rect[1], rect[3]), y1 = Math.max(rect[1], rect[3]);
    const fm = /(-?\d+(?:\.\d+)?)\s+Tf\b/.exec(da);
    let size = fm !== null ? parseFloat(fm[1]) : 0;
    if (!(size > 0)) size = Math.max(4, Math.min(12, (y1 - y0) * 0.7));
    // (Helvetica-like widths: half the font size per character)
    const w = Math.min(s.length * size * 0.5, Math.max(x1 - x0 - 4, 1));
    const x = q === 2 ? x1 - 2 - w : q === 1 ? (x0 + x1 - w) / 2 : x0 + 2;
    const y = y0 + Math.max(0, (y1 - y0 - size) / 2) + size * 0.22;
    this.items.push({ x: x, y: y, w: w, h: size, s: s, sp: size * 0.278, page: page, flip: false, rot: 0 });
  }

  private showText(gs: GState, tm: Mat, str: string, page: number): Mat {
    // returns the text matrix advanced past the shown string
    const f = gs.font;
    if (!f) {
      // no font selected: still advance roughly so following text is placed sensibly
      return matMul([1, 0, 0, 1, str.length * 0.5 * gs.size * gs.hscale, 0], tm);
    }
    const glyphs = this.fonts.decode(f, str);
    const trm: Mat = matMul(matMul([gs.size * gs.hscale, 0, 0, gs.size, 0, gs.rise], tm), gs.ctm);
    const scale = Math.sqrt(trm[0] * trm[0] + trm[1] * trm[1]) / Math.max(gs.size * gs.hscale, 1e-9);
    let text = "";
    let advance = 0; // text space units (before hscale)
    let noUni = 0;
    for (const g of glyphs) {
      const w0 = g.w / 1000;
      let tx = w0 * gs.size + gs.charSp;
      if (g.isSpace) tx += gs.wordSp;
      advance += tx;
      text += g.u;
      const c0 = g.u.length > 0 ? g.u.charCodeAt(0) : 0;
      if (c0 === 0 || c0 === 0xfffd || (c0 >= 0xe000 && c0 <= 0xf8ff)) noUni++;
    }
    // some producers (Chrome/Skia) map the space glyph to a line break: keep text runs on one line
    if (/[\t\n\v\f\r]/.test(text)) text = text.replace(/[\t\n\v\f\r]/g, " ");
    const devW = advance * gs.hscale * scale;
    const devH = Math.abs(gs.size * Math.sqrt(trm[2] * trm[2] + trm[3] * trm[3]) / Math.max(gs.size, 1e-9));
    if (this.ocHidden === 0 && glyphs.length > 0) {
      // statistics for the OCR / Unicode checks (text in hidden optional content does not count)
      this.glyphsTotal += glyphs.length;
      this.glyphsNoUni += noUni;
      if (f.ocrFont || invisibleText(gs)) this.glyphsOcr += glyphs.length;
      else this.pageNative += glyphs.length;
    }
    if (text.length > 0 && this.ocHidden === 0) {
      let rot = Math.round(Math.atan2(trm[1], trm[0]) / (Math.PI / 2)) % 4;
      if (rot < 0) rot += 4;
      this.items.push({ x: trm[4], y: trm[5], w: devW, h: devH > 0 ? devH : Math.abs(gs.size * scale), s: text, sp: (f.spaceWidth / 1000) * gs.size * gs.hscale * scale, page: page, flip: false, rot: rot });
    }
    return matMul([1, 0, 0, 1, advance * gs.hscale, 0], tm);
  }

  private paintImage(gs: GState, img: PDict | null): void {
    // a page-filling opaque image: text drawn before it on this page is hidden under the image
    if (gs.fa < 0.99 || gs.mask || gs.blend || this.pageArea <= 0) return;
    if (img && (img.m.has("SMask") || img.m.has("Mask") || this.doc.resolve(img.m.get("ImageMask")) === true)) return;
    const m = gs.ctm;
    const area = Math.abs(m[0] * m[3] - m[1] * m[2]);
    if (area < 0.5 * this.pageArea) return;
    this.pageHasImage = true;
    this.glyphsCovered += this.pageNative;
    this.pageNative = 0;
  }

  private extGState(gs: GState, resources: PDict | null, name: PObj): void {
    // transparency from an ExtGState (fill alpha, soft mask, blend mode)
    if (!isName(name) || !resources) return;
    const doc = this.doc;
    const egs = doc.dictOf(resources.m.get("ExtGState"));
    const d = egs ? doc.dictOf(egs.m.get(name.v)) : null;
    if (!d) return;
    if (d.m.has("ca")) gs.fa = doc.num(d.m.get("ca"), 1);
    if (d.m.has("CA")) gs.sa = doc.num(d.m.get("CA"), 1);
    const sm = d.m.get("SMask");
    if (sm !== undefined) gs.mask = doc.nameOf(sm) !== "None";
    if (d.m.has("BM")) {
      const bm = doc.nameOf(d.m.get("BM"));
      gs.blend = bm !== "" && bm !== "Normal" && bm !== "Compatible";
    }
  }

  private run(content: string, resources: PDict | null, gsIn: GState, page: number, visited: Set<number>): void {
    const doc = this.doc;
    const lx = new Lexer(content, 0);
    const stack: PObj[] = [];
    const gsStack: GState[] = [];
    const mcStack: boolean[] = []; // marked content: true = hidden optional content
    let gs: GState = gsIn;
    let tm: Mat = [1, 0, 0, 1, 0, 0];
    let tlm: Mat = [1, 0, 0, 1, 0, 0];
    const fontDict = resources ? doc.dictOf(resources.m.get("Font")) : null;
    const xobjDict = resources ? doc.dictOf(resources.m.get("XObject")) : null;

    let guard = 0;
    // One try guards the whole loop: each executed try costs milliseconds in Office Scripts, one per token made a
    // two-page PDF take 90 s. step 1 = reading the next token (a failure ends the stream), step 2 = running a
    // form XObject (a failure skips that form); other exceptions propagate as before.
    let step = 0;
    let formName = "";
    let formId = -1;
    let formSaved: GState = gs;
    for (;;) {
      try {
        for (;;) {
          if (++guard > 5000000) { doc.flagIncomplete("operator limit reached"); break; }
          if ((guard & 4095) === 0 && Date.now() > this.deadline) {
            doc.warnings.push("time budget exhausted, text truncated");
            doc.flagIncomplete("time budget exhausted");
            break;
          }
          step = 1;
          const o = lx.parse(0);
          step = 0;
          if (o === null) { if (lx.pos >= content.length) break; stack.push(null); continue; }
          if (!isKw(o)) { stack.push(o); if (stack.length > 64) stack.shift(); continue; }
          const op = o.v;
          this.ops++;
          const n = (i: number): number => { const v = stack[stack.length - i]; return typeof v === "number" ? v : 0; };
          switch (op) {
            case "q": gsStack.push(copyGState(gs)); if (gsStack.length > 256) gsStack.shift(); break;
            case "Q": { const p = gsStack.pop(); if (p) gs = p; break; }
            case "cm": if (stack.length >= 6) gs.ctm = matMul([n(6), n(5), n(4), n(3), n(2), n(1)], gs.ctm); break;
            case "gs": this.extGState(gs, resources, stack[stack.length - 1]); break;
            case "BT": tm = [1, 0, 0, 1, 0, 0]; tlm = [1, 0, 0, 1, 0, 0]; break;
            case "ET": break;
            case "Tf": {
              gs.size = n(1);
              const nm = stack[stack.length - 2];
              let fobj: PObj | undefined = undefined;
              if (isName(nm) && fontDict) fobj = fontDict.m.get(nm.v);
              const loaded = fobj !== undefined ? this.fonts.load(fobj) : null;
              gs.font = loaded ? loaded : (gs.font ? gs.font : this.fonts.fallback());
              break;
            }
            case "Td": tlm = matMul([1, 0, 0, 1, n(2), n(1)], tlm); tm = tlm; break;
            case "TD": gs.leading = -n(1); tlm = matMul([1, 0, 0, 1, n(2), n(1)], tlm); tm = tlm; break;
            case "Tm": if (stack.length >= 6) { tlm = [n(6), n(5), n(4), n(3), n(2), n(1)]; tm = tlm; } break;
            case "T*": tlm = matMul([1, 0, 0, 1, 0, -gs.leading], tlm); tm = tlm; break;
            case "TL": gs.leading = n(1); break;
            case "Tc": gs.charSp = n(1); break;
            case "Tw": gs.wordSp = n(1); break;
            case "Tz": gs.hscale = n(1) / 100; break;
            case "Ts": gs.rise = n(1); break;
            case "Tr": gs.tr = n(1); break;
            case "Tj": { const s = stack[stack.length - 1]; if (isStr(s)) tm = this.showText(gs, tm, s.v, page); break; }
            case "'": { tlm = matMul([1, 0, 0, 1, 0, -gs.leading], tlm); tm = tlm; const s = stack[stack.length - 1]; if (isStr(s)) tm = this.showText(gs, tm, s.v, page); break; }
            case "\"": { gs.wordSp = n(3); gs.charSp = n(2); tlm = matMul([1, 0, 0, 1, 0, -gs.leading], tlm); tm = tlm; const s = stack[stack.length - 1]; if (isStr(s)) tm = this.showText(gs, tm, s.v, page); break; }
            case "TJ": {
              const a = stack[stack.length - 1];
              if (isArr(a)) {
                for (const el of a.v) {
                  if (isStr(el)) tm = this.showText(gs, tm, el.v, page);
                  else if (isNum(el)) tm = matMul([1, 0, 0, 1, (-el / 1000) * gs.size * gs.hscale, 0], tm);
                }
              }
              break;
            }
            case "BMC": mcStack.push(false); break;
            case "BDC": {
              let hidden = false;
              const tag = stack[stack.length - 2];
              if (isName(tag) && tag.v === "OC") {
                const prop = stack[stack.length - 1];
                if (isName(prop)) {
                  const props = resources ? doc.dictOf(resources.m.get("Properties")) : null;
                  hidden = props ? doc.isHiddenOC(props.m.get(prop.v)) : false;
                } else if (isDict(prop)) hidden = doc.isHiddenOC(prop);
              }
              mcStack.push(hidden);
              if (hidden) this.ocHidden++;
              break;
            }
            case "EMC": { const h = mcStack.pop(); if (h === true) this.ocHidden--; break; }
            case "Do": {
              const nm = stack[stack.length - 1];
              if (isName(nm) && xobjDict) {
                const xo = doc.resolve(xobjDict.m.get(nm.v));
                if (!isStream(xo) || doc.isHiddenOC(xo.d.m.get("OC"))) break;
                const subtype = doc.nameOf(xo.d.m.get("Subtype"));
                if (subtype === "Image") {
                  if (this.ocHidden === 0) this.paintImage(gs, xo.d);
                } else if (subtype === "Form" && !visited.has(xo.id)) {
                  if (this.formDepth >= 12) { doc.flagIncomplete("form XObjects nested too deeply"); break; }
                  // many small forms calling each other never reach the per-stream check below
                  if (Date.now() > this.deadline) { doc.flagIncomplete("time budget exhausted"); break; }
                  visited.add(xo.id);
                  this.formDepth++;
                  const saved = gs;
                  const sub = copyGState(gs);
                  const mtx = doc.arrOf(xo.d.m.get("Matrix"));
                  if (mtx.length === 6) sub.ctm = matMul([doc.num(mtx[0], 1), doc.num(mtx[1], 0), doc.num(mtx[2], 0), doc.num(mtx[3], 1), doc.num(mtx[4], 0), doc.num(mtx[5], 0)], sub.ctm);
                  const res = doc.dictOf(xo.d.m.get("Resources")) || resources;
                  formName = nm.v;
                  formId = xo.id;
                  formSaved = saved;
                  step = 2;
                  this.run(doc.streamText(xo), res, sub, page, visited);
                  step = 0;
                  gs = saved;
                  this.formDepth--;
                  visited.delete(xo.id);
                }
              }
              break;
            }
            case "BI": {
              // inline image: skip "... ID <binary> EI"
              const s = content;
              let p = lx.pos;
              const idIdx = s.indexOf("ID", p);
              if (idIdx < 0) { lx.pos = s.length; break; }
              if (this.ocHidden === 0 && !/\/(IM|ImageMask)\s+true/.test(s.substring(p, idIdx))) this.paintImage(gs, null);
              p = idIdx + 3;
              for (;;) {
                const ei = s.indexOf("EI", p);
                if (ei < 0) { p = s.length; break; }
                const before = s.charCodeAt(ei - 1), after = ei + 2 < s.length ? s.charCodeAt(ei + 2) : 32;
                if (isWs(before) && (isWs(after) || isDelim(after))) { p = ei + 2; break; }
                p = ei + 2;
              }
              lx.pos = p;
              break;
            }
            default: break;
          }
          stack.length = 0;
        }
        break;
      } catch (e) {
        if (step === 1) { doc.flagIncomplete("content stream could not be parsed"); break; }
        if (step !== 2) throw e;
        step = 0;
        doc.warnings.push("XObject " + formName + ": " + String(e));
        doc.flagIncomplete("form XObject " + formName + " could not be read");
        gs = formSaved;
        this.formDepth--;
        visited.delete(formId);
        stack.length = 0;
      }
    }
    if (lx.unterminated) doc.flagIncomplete("unterminated string in a content stream");
    // unbalanced BDC inside this stream must not hide text outside it
    for (const h of mcStack) if (h) this.ocHidden--;
  }

  private deskew(): void {
    // Skewed scans with an OCR layer: estimate the page's text angle from consecutive items in
    // stream order (words of one line) and rotate the positions back. Native text gives 0.
    const byPage = new Map<number, number[]>();
    const items = this.items;
    for (let i = 0; i + 1 < items.length; i++) {
      const a = items[i], b = items[i + 1];
      if (a.page !== b.page || a.rot !== 0 || b.rot !== 0) continue;
      const dx = b.x - a.x, dy = b.y - a.y;
      if (dx <= Math.max(a.h, 1) || Math.abs(dy) > dx * 0.0875) continue; // within 5 degrees
      let list = byPage.get(a.page);
      if (!list) { list = []; byPage.set(a.page, list); }
      list.push(Math.atan2(dy, dx));
    }
    for (const [page, angles] of Array.from(byPage.entries())) {
      if (angles.length < 4) continue;
      angles.sort((p, q) => p - q);
      const med = angles[angles.length >> 1];
      if (Math.abs(med) < 0.0017) continue; // < 0.1 degree
      // native text: many neighbours share the exact same baseline; a skewed scan has (almost) none
      let flat = 0;
      for (const ang of angles) if (Math.abs(ang) < 0.0001) flat++;
      if (flat * 4 >= angles.length) continue;
      const c = Math.cos(med), sn = Math.sin(med);
      for (const it of items) {
        if (it.page !== page || it.rot !== 0) continue;
        const x = it.x, y = it.y;
        it.x = x * c + y * sn;
        it.y = -x * sn + y * c;
      }
    }
  }

  finishItems(boxes: number[][]): TextItem[] {
    // Drops text outside the page box (when most of the page's text is inside it), straightens
    // skewed OCR pages and drops text drawn twice at (almost) the same place (same string,
    // > 50 % overlap along the line). boxes[i] is the box of page i.
    this.items = dropOffPage(this.items, boxes);
    this.deskew();
    const out: TextItem[] = [];
    const buckets = new Map<string, TextItem[]>();
    for (const it of this.items) {
      // coordinates along (u) and across (v) the text direction
      const u = it.rot === 0 ? it.x : it.rot === 1 ? it.y : it.rot === 2 ? -it.x : -it.y;
      const v = it.rot === 0 ? it.y : it.rot === 1 ? -it.x : it.rot === 2 ? -it.y : it.x;
      const b = Math.floor(v / 4);
      let dup = false;
      for (let k = b - 1; k <= b + 1 && !dup; k++) {
        const list = buckets.get(it.page + "|" + it.rot + "|" + k + "|" + it.s);
        if (!list) continue;
        for (const o of list) {
          const ou = o.rot === 0 ? o.x : o.rot === 1 ? o.y : o.rot === 2 ? -o.x : -o.y;
          const ov = o.rot === 0 ? o.y : o.rot === 1 ? -o.x : o.rot === 2 ? -o.y : o.x;
          const h = Math.max(it.h, o.h, 1);
          if (Math.abs(ov - v) > 0.5 * h) continue;
          const minW = Math.min(it.w, o.w);
          if (minW < 0.01) { if (Math.abs(ou - u) < 0.15 * h) { dup = true; break; } continue; }
          const overlap = Math.min(u + it.w, ou + o.w) - Math.max(u, ou);
          if (overlap > 0.5 * minW) { dup = true; break; }
        }
      }
      if (dup) continue;
      const key = it.page + "|" + it.rot + "|" + b + "|" + it.s;
      let own = buckets.get(key);
      if (!own) { own = []; buckets.set(key, own); }
      own.push(it);
      out.push(it);
    }
    return out;
  }
}

function dropOffPage(items: TextItem[], boxes: number[][]): TextItem[] {
  // Drops items outside their page box (+ margin) when most items of that page are inside;
  // boxes[i] belongs to page i.
  const inside = new Map<number, number>(), outside = new Map<number, number>();
  const flags: boolean[] = [];
  for (const it of items) {
    const b = boxes[it.page];
    let ok = true;
    if (b && b.length === 4 && b[2] - b[0] > 1 && b[3] - b[1] > 1) {
      const m = 10;
      ok = it.x >= b[0] - m && it.x <= b[2] + m && it.y >= b[1] - m && it.y <= b[3] + m;
    }
    flags.push(ok);
    const map = ok ? inside : outside;
    map.set(it.page, (map.get(it.page) || 0) + 1);
  }
  const out: TextItem[] = [];
  for (let i = 0; i < items.length; i++) {
    const p = items[i].page;
    if (flags[i] || (inside.get(p) || 0) < (outside.get(p) || 0)) out.push(items[i]);
  }
  return out;
}

// PDFDocEncoding of the bytes 0x80-0x9E and 0xA0 (bullet, daggers, dashes, quotes, ligatures; 0xA0 is the euro sign)
const PDFDOC_HIGH = "\u2022\u2020\u2021\u2026\u2014\u2013\u0192\u2044\u2039\u203a\u2212\u2030\u201e\u201c\u201d\u2018\u2019\u201a\u2122\ufb01\ufb02\u0141\u0152\u0160\u0178\u017d\u0131\u0142\u0153\u0161\u017e";

function pdfTextString(s: string): string {
  // a PDF text string (form field values, document information): UTF-16BE or UTF-8 with a byte order mark, else
  // PDFDocEncoding
  if (s.length >= 2 && s.charCodeAt(0) === 0xfe && s.charCodeAt(1) === 0xff) return utf16beToString(s.substring(2));
  if (s.length >= 3 && s.charCodeAt(0) === 0xef && s.charCodeAt(1) === 0xbb && s.charCodeAt(2) === 0xbf) return utf8Decode(latin1ToBytes(s.substring(3)));
  let out = "";
  for (let i = 0; i < s.length && i < 4000; i++) {
    const c = s.charCodeAt(i) & 0xff;
    out += c >= 0x80 && c <= 0x9e ? PDFDOC_HIGH.charAt(c - 0x80) : c === 0xa0 ? "\u20ac" : String.fromCharCode(c);
  }
  return out;
}

// ---------------------------------------------------------------------
// Line assembly
// ---------------------------------------------------------------------
// Largest glyph height of every line of the last assembleLines call (0 for a page break); pickAmount uses it to find the title.
let lastLineHeights: number[] = [];
// Name words of the mailbox the mail was delivered to, from its company's mail domain ("debitoren@nordwerk.example" ->
// "nordwerk"; see ownerWords); set for each mail by mailResult, empty for a document passed alone. A careful clerk finds
// the own line in a payment register and tells an incoming from an own outgoing payment by the own name.
let mailOwner: string[] = [];
// the same for the sender's company when it is another one (a payer named like the mailbox owner is the sender)
let mailSender: string[] = [];
// the text being read is the writer's own text of a reply from outside the mailbox's domain to the mailbox owner's request
// for payment (open items, a reminder; see paymentRequestReply): set by mailResult for that text only
let mailReplyToOwner = false;
// the day the mail was written (its Date header, y * 372 + m * 31 + d; 0 for a document passed alone): the date of a text
// that names none, against which a payment date is later ("wird mit unserem Zahllauf am 13.11.2026 überwiesen" in a mail of
// 30.10.2026)
let mailDay = 0;
// the mailbox owner's name words are written in the texts of the mail (a signature, an address, a quoted mail; not only in
// mail addresses): only then do its name words tell its company from another one named in a document
let mailOwnerSeen = false;

function assembleLines(items: TextItem[]): string[] {
  const lines: string[] = [];
  const heights: number[] = [];
  let page = -1;
  // group per page, sort by y desc then x asc
  const byPage = new Map<number, TextItem[]>();
  for (const it of items) {
    let arr = byPage.get(it.page);
    if (!arr) { arr = []; byPage.set(it.page, arr); }
    arr.push(it);
  }
  const pageNums: number[] = [];
  for (const k of Array.from(byPage.keys())) pageNums.push(k);
  pageNums.sort((a, b) => a - b);
  for (const pn of pageNums) {
    const arr = byPage.get(pn) as TextItem[];
    if (page >= 0) { lines.push(""); heights.push(0); }
    page = pn;
    // dominant text direction on this page (rotated/landscape text): rotate coordinates back
    const rotCount = [0, 0, 0, 0];
    for (const it of arr) rotCount[it.rot]++;
    let dom = 0;
    for (let k = 1; k < 4; k++) if (rotCount[k] > rotCount[dom]) dom = k;
    if (dom !== 0) {
      for (const it of arr) {
        const x = it.x, y = it.y;
        if (dom === 1) { it.x = y; it.y = -x; }
        else if (dom === 2) { it.x = -x; it.y = -y; }
        else { it.x = -y; it.y = x; }
      }
    }
    let flips = 0;
    for (const it of arr) if (it.flip) flips++;
    const flipped = dom === 0 && flips * 2 > arr.length; // y grows downwards in this page's coordinate system
    arr.sort((a, b) => (flipped ? a.y - b.y : b.y - a.y) || (a.x - b.x));
    // cluster into lines by baseline
    const groups: TextItem[][] = [];
    let cur: TextItem[] = [];
    let curY = 0, curH = 0;
    for (const it of arr) {
      const h = Math.max(it.h, 1);
      const tol = Math.max(0.45 * Math.max(h, curH), 1.5);
      if (cur.length > 0 && Math.abs(it.y - curY) > tol) {
        groups.push(cur);
        cur = [];
      }
      if (cur.length === 0) { curY = it.y; curH = h; }
      cur.push(it);
    }
    if (cur.length > 0) groups.push(cur);
    for (const g of groups) {
      g.sort((a, b) => a.x - b.x);
      let line = "";
      let endX = -1e9;
      let prevText = "";
      let prevX = -1e9;
      let h = 0;
      let maxH = 0;
      for (const it of g) {
        h = Math.max(it.h, 1);
        const t = it.s;
        if (t.length === 0) continue;
        if (it.h > maxH && t.trim().length > 0) maxH = it.h;
        // duplicated text (fake bold / overprint)
        if (t === prevText && Math.abs(it.x - prevX) < 0.15 * h) continue;
        if (endX > -1e8) {
          const gap = it.x - endX;
          const spaceW = it.sp > 0 ? it.sp : 0.25 * h;
          if (gap > 1.6 * h) line += "   ";
          else if (gap > Math.min(0.5 * spaceW, 0.22 * h) && line.length > 0 && !line.endsWith(" ") && !t.startsWith(" ")) line += " ";
        }
        line += t;
        endX = Math.max(endX, it.x + it.w);
        prevText = t;
        prevX = it.x;
      }
      // trailing white space, without a regex (/\s+$/ is quadratic on long runs of inner spaces)
      let e = line.length;
      while (e > 0 && /\s/.test(line.charAt(e - 1))) e--;
      if (e < line.length) line = line.substring(0, e);
      if (line.length > 0) { lines.push(line); heights.push(maxH); }
    }
  }
  lastLineHeights = heights;
  return lines;
}


// ---------------------------------------------------------------------
// Amount extraction
// ---------------------------------------------------------------------
// One amount found in a line: printed text, value and position.
interface AmountMatch { text: string; value: number; index: number; end: number }

// Keyword classes of the label that belongs to one amount.
interface LabelInfo { strong: boolean; payment: boolean; weak: boolean; neg: boolean; ded: boolean }

interface Candidate {
  amount: string; value: number; score: number; line: string; lineIdx: number; method: string;
  pos: number;          // index of the amount within its line, -1 for keyword-next-line
  charIdx: number;      // position of the amount text in its line
  label: LabelInfo;     // own label segment, or the line label for table cells
  lineLabel: boolean;   // amount carries the line's first label (table cell / total row)
  ownLabel: boolean;    // amount has its own text label (not a bare table cell)
  confirmed: boolean;   // backed by arithmetic (column sum, sum check, deduction chain)
  copy: boolean;        // inside an appended invoice copy
  risky: boolean;       // table whose rightmost amount column is Skonto / Rest / Offen
  col: string;          // column class from the table header ("" = unmapped)
}

interface LineInfo {
  text: string;
  amounts: AmountMatch[];
  labels: LabelInfo[];
  lineLabel: boolean[];
  own: boolean[];
  cols: string[];
  pcts: number[];       // percentages written in the line ("2 % Skonto")
  label: LabelInfo;     // keyword classes of the whole line
  header: boolean;
  risky: boolean;
  payBonus: boolean;    // header-mapped payment column counts as a label on this line
  copy: boolean;
  wrapped: string;      // label wrapped around a value-only line ("" if none)
  grossPay: boolean;    // single invoice row under a Netto/USt/Brutto header without payment or deduction column
  payCol: boolean;      // row under a header that has a payment column (Zahlbetrag)
  quoted: boolean;      // quoted part of an e-mail reply
  sents: string[];      // the sentence around each amount (letter text, across wrapped lines)
  pconf: boolean[];     // payment confirmed by the arithmetic of its sentence (prose)
}

// doc: the document type found by classifyDocument; ev: what speaks for or against a payment advice (verdict of the
// document in a mail; neither changes the amount nor the confidence); curHow: "" when the document shows the currency,
// "$" for a bare dollar sign it does not explain (read as US dollars), "none" when it shows no currency (read as euros);
// curSplit: payment totals in different currencies ("3,747.83 USD; 22,257.84 EUR": separate payments), "" otherwise
interface AmountPick { best: Candidate | null; candidates: Candidate[]; currency: string; curHow: string; curSplit: string; curAmounts: string[]; confidence: string; reason: string; doc: DocInfo; ev: AdviceEvidence }

// total and payment labels (also NL, FR, IT, ES, PT, PL, CZ, DA/SV totals, "paid" participles and transfer nouns)
const STRONG_KEYWORDS = /gesamt|zahlbetrag|auszuzahlende[rn]? betrag|payout total|transfer to (?:your )?bank(?: account)?|funds transferred|net remitted|total remitted|remitted amount|net payout|total payout|payout amount|amount paid out|paid out|amount disbursed|disbursement amount|zahlungsbetrag|überweisungsbetrag|ueberweisungsbetrag|überweisungssumme|auszahlungsbetrag|auszahlung\b|gutschriftsbetrag|erstattungsbetrag|endbetrag|endsumme|summe|total|nettobetrag der zahlung|betrag der überweisung|wir überweisen|überwiesen|ueberwiesen|überweisen wir|überweisen ihnen|zahlung in höhe|zahlen wir|wir zahlen|zu zahlen|angewiesen|den betrag von|gutgeschrieben|zu ihren gunsten|betrag der zahlung|überweisung\b|ueberweisung\b|ausgleichsbetrag|gezahlte[rn]? betrag|bezahlte[rn]? betrag|nettozahlung|gutschrift auf ihr konto|remittance total|remittance amount|payment amount|payment value(?! date)|net amount paid|net payment|total paid|payment total|check amount|credited amount|amount credited|transfer amount|we have (?:today )?(?:paid|transferred|remitted)|payment of\b|totaal|celkem|\bi alt\b|totalt|\bsumma\b|\bsuma\b|razem|betaald|overgemaakt|overboeking|réglé|reglé|payé|viré|versé|virement|pagato|bonifico|bonificato|pagado|transferencia|transferido|abonado|valor pago|montante pago|total pago|transferência|przelew|przelano|zapłacono|zapłacona|wpłacono|uregulowano|uhrazen|zaplacen|převedeno|betalt|overført|indbetalt|överfört|utbetalt|nous avons (?:réglé|payé|viré|versé)|wij hebben (?:betaald|overgemaakt)|abbiamo (?:pagato|bonificato|saldato)|hemos (?:pagado|transferido|abonado)|efetu[aá]mos|pagámos|transferimos|uhradili jsme|jsme uhradili|zaplatili jsme|jsme zaplatili|převedli jsme|przelaliśmy|zapłaciliśmy|uregulowaliśmy|vi har (?:betalt|overført|betalat|överfört)|montant (?:du |de )?(?:règlement|reglement|paiement|virement)|importo (?:del )?(?:pagamento|bonifico)|importe (?:del )?(?:pago|transferencia)|bedrag (?:van de )?betaling|kwota (?:płatności|przelewu)|částka (?:platby|úhrady)|(?:transferred|remitted) to your (?:bank )?account|(?:net|total) remittance|amount (?:actually |effectively )?remitted|amount (?:actually |effectively )?paid|amount (?:actually |effectively )?transferred|dividend paid|amount of (?:this|the) payment|betrag dieser zahlung|(?:eft|bacs|chaps) (?:amount|total)|(?:^|\s)payout\s*:?\s*(?:[€$£]|eur|usd|gbp|chf)?\s*$|(?:^|[^a-zäöüß])(?:an sie|auf ihr (?:bank)?konto) (?:überwiesen|ueberwiesen|ausgezahlt)(?![a-zäöüß])|\b(?:paid|transferred|remitted) to you\b/i;
// words that mean "what was actually paid" (also the foreign participles and transfer nouns) – beat generic totals like "Summe Rechnungsbetrag"
// (a label that ends with "Payout" names the amount paid out: "Payout   €13,316.77", "Seller payout"; "Next payout" is
// pending, PENDING_LABEL; "Amount of this payment", "EFT amount released" name the payment too; not "WIRE AMOUNT" of a
// bank's report that lists the wires of many payers)
const PAYMENT_KEYWORDS = /zahlbetrag|gesamtzahlung|auszuzahlende[rn]? betrag|payout total|transfer to (?:your )?bank(?: account)?|funds transferred|zahlung gesamt|net remitted|total remitted|remitted amount|net payout|total payout|payout amount|amount paid out|paid out|amount disbursed|disbursement amount|zahlungsbetrag|überweisungsbetrag|ueberweisungsbetrag|überweisungssumme|auszahlung|gutschriftsbetrag|erstattungsbetrag|wir überweisen|überwiesen|ueberwiesen|überweisen wir|überweisen ihnen|zahlung in höhe|zahlen wir|wir zahlen|zu zahlen|angewiesen|den betrag von|gutgeschrieben|zu ihren gunsten|betrag der zahlung|überweisung\b|ueberweisung\b|zahlungssumme|ausgleichsbetrag|gezahlte[rn]? betrag|bezahlte[rn]? betrag|nettozahlung|gutschrift auf ihr konto|remittance total|remittance amount|payment amount|payment value(?! date)|net amount paid|net payment|total paid|payment total|check amount|credited amount|amount credited|transfer amount|we have (?:today )?(?:paid|transferred|remitted)|payment of\b|betaald|overgemaakt|overboeking|réglé|reglé|payé|viré|versé|virement|pagato|bonifico|bonificato|pagado|transferencia|transferido|abonado|valor pago|montante pago|total pago|transferência|przelew|przelano|zapłacono|zapłacona|wpłacono|uregulowano|uhrazen|zaplacen|převedeno|betalt|overført|indbetalt|överfört|utbetalt|nous avons (?:réglé|payé|viré|versé)|wij hebben (?:betaald|overgemaakt)|abbiamo (?:pagato|bonificato|saldato)|hemos (?:pagado|transferido|abonado)|efetu[aá]mos|pagámos|transferimos|uhradili jsme|jsme uhradili|zaplatili jsme|jsme zaplatili|převedli jsme|przelaliśmy|zapłaciliśmy|uregulowaliśmy|vi har (?:betalt|overført|betalat|överfört)|montant (?:du |de )?(?:règlement|reglement|paiement|virement)|importo (?:del )?(?:pagamento|bonifico)|importe (?:del )?(?:pago|transferencia)|bedrag (?:van de )?betaling|kwota (?:płatności|przelewu)|částka (?:platby|úhrady)|(?:transferred|remitted) to your (?:bank )?account|(?:net|total) remittance|amount (?:actually |effectively )?remitted|amount (?:actually |effectively )?paid|amount (?:actually |effectively )?transferred|dividend paid|amount of (?:this|the) payment|betrag dieser zahlung|(?:eft|bacs|chaps) (?:amount|total)|(?:^|\s)payout\s*:?\s*(?:[€$£]|eur|usd|gbp|chf)?\s*$|(?:^|[^a-zäöüß])(?:an sie|auf ihr (?:bank)?konto) (?:überwiesen|ueberwiesen|ausgezahlt)(?![a-zäöüß])|\b(?:paid|transferred|remitted) to you\b/i;
// the amount actually paid, beside a payment figure it corrects ("The amount actually remitted to your account is EUR
// 5,355.00", "der tatsächlich überwiesene Betrag"); not an earlier payment cited against a reminder or a statement ("We
// actually paid it on 3 October", "haben wir tatsächlich schon bezahlt ... am 03.10.2026": earlierPaid)
const ACTUAL_PAID = /\b(?:actually|effectively|in fact)\s+(?:been\s+)?(?:paid|remitted|transferred|credited|sent|wired)\b|(?:^|[^a-zäöüß])tatsächlich\s+(?:[a-zäöüß]+\s+){0,2}?(?:überwiesen|ueberwiesen|bezahlt|gezahlt|gutgeschrieben|überwiesene[nrs]?|gezahlte[nrs]?|gutgeschriebene[nrs]?)(?![a-zäöüß])/i;
// explicit label of the transferred amount (the end of a netting): beats computed totals; also the transfer to the reader
// stated as the label ("an Sie überwiesen am 21.10.2026   48.716,62", "Amount paid to you")
const TRANSFER_LABEL = /überweisungsbetrag|gesamtzahlung|auszuzahlende[rn]? betrag|payout total|transfer to (?:your )?bank(?: account)?|funds transferred|net remitted|total remitted|remitted amount|net payout|total payout|payout amount|amount paid out|amount disbursed|disbursement amount|ueberweisungsbetrag|überweisungssumme|auszahlungsbetrag|auszahlbetrag|auszahlung\b|gutschriftsbetrag|erstattungsbetrag|zahlbetrag|zahlungsbetrag|zahlungssumme|überwiesene[rn]? (?:betrag|summe)|gezahlte[rn]? betrag|betrag der überweisung|betrag der zahlung|nettozahlung|payment amount|payment value(?! date)|net payment|total paid|remittance (?:amount|total)|transfer amount|check amount|credited amount|amount credited|totaal betaald|betaald bedrag|montant (?:réglé|payé|du virement|viré|versé)|total (?:réglé|payé|pagado|pago)|importo (?:pagato|bonificato|del bonifico)|totale pagato|importe (?:pagado|transferido|de la transferencia)|valor (?:pago|transferido)|montante pago|kwota (?:przelewu|zapłacona|płatności)|zapłacono|uhrazen[áo]|částka platby|zaplacen[áo] částka|betalt beløb|betalt belopp|montant (?:du |de )?(?:règlement|reglement|paiement|virement)|importo (?:del )?(?:pagamento|bonifico)|importe (?:del )?(?:pago|transferencia)|bedrag (?:van de )?betaling|částka úhrady|(?:transferred|remitted) to your (?:bank )?account|amount (?:actually |effectively )?paid|(?:net|total) remittance|amount (?:actually |effectively )?remitted|amount (?:actually |effectively )?transferred|amount of (?:this|the) payment|betrag dieser zahlung|(?:eft|bacs|chaps) (?:amount|total)|(?:^|\s)payout\s*:?\s*(?:[€$£]|eur|usd|gbp|chf)?\s*$|(?:^|[^a-zäöüß])(?:an sie|auf ihr (?:bank)?konto) (?:überwiesen|ueberwiesen|ausgezahlt)(?![a-zäöüß])|\b(?:paid|transferred|remitted) to you\b/i;
// payment verbs that follow the amount in a sentence ("3.454,00 EUR überwiesen")
const POST_PAYMENT = /überwiesen|ueberwiesen|überweisen|gutgeschrieben|angewiesen|bezahlt|beglichen|ausgeglichen|geleistet|transferred|remitted|paid\b|betaald|overgemaakt|réglé|payé|viré|pagato|bonificato|pagado|transferido|zapłacono|przelano|uhrazen|zaplacen|betalt|overført|överfört/i;
// label nouns that must be followed by an amount (safety net)
const PAYMENT_LABEL = /zahlbetrag|zahlungsbetrag|überweisungsbetrag|ueberweisungsbetrag|überweisungssumme|auszahlungsbetrag|gutschriftsbetrag|zahlungssumme|betrag der zahlung|payment amount|payment value(?! date)|amount (?:actually |effectively )?paid|net payment|total paid|credited amount|amount credited/i;
// running totals and balances are no payment, even when worded like one ("Saldo zu Ihren Gunsten", "bisher überwiesen")
const CUMULATIVE = /(?:saldo|guthaben|kontostand)[^.]{0,25}zu ihren gunsten|\bbisher\b/i;
const YEAR_TO_DATE = /year to date|\bytd\b|laufenden jahr|kumuliert|\bto date\b|\bso far\b|cumulative|running total|bislang/i;
// a limit, the amount still available or the account balance beside the transfer in a bank form ("Tageslimit
// Echtzeitüberweisung", "Noch verfügbar", "Available balance after this payment", "Kontostand nach Umsatz"): never the
// payment, even when the label names the transfer
const LIMIT_BALANCE = /limit(?!ed\b|ation)|verfügungsrahmen|kreditrahmen|(?:noch|jetzt) verfügbar|verfügbare[rsn]? (?:betrag|saldo|guthaben|rahmen)|available (?:balance|limit|credit|funds)|(?:balance|limit|credit) available|remaining (?:limit|credit)|kontostand|(?:account|ledger|book|closing|opening|current|new|old|previous) balance|balance (?:after|before) (?:this |the )?(?:payment|transfer|transaction|booking)|(?:alter|neuer) saldo|\bsaldo (?:alt|neu)\b/i;
// earlier payments named in a label ("bereits gezahlt", "1. Rate (bereits überwiesen am 15.09.)") and unpaid amounts
const PRIOR = /\bbereits\b|\bschon\b|\bzuvor\b|already|previously|prior payment|déjà|\breeds\b|\bgià\b|\bya\b|\bjiž\b|\bjuż\b|allerede|\bredan\b/i;
const PRIOR_PAID = /gezahlt|bezahlt|überwiesen|ueberwiesen|beglichen|angewiesen|zahlung|paid|payment|betaald|payé|réglé|pagat|pagad|zapłac|uhrazen|zaplacen|betalt/i;
const SENTENCE_VERB = /\b(?:wir|haben|hat|habe|wurde|wurden|we|have|has|nous|avons|wij|hebben|abbiamo|hemos)\b/i;
const NOT_PAID = /obetal|ikke betalt|niet betaald|onbetaald|non pagat|impagad|no pagad|nezaplacen|neuhrazen|niezapłac|impayé|non réglé|unpaid|unbezahlt|nicht bezahlt/i;
// a label of an amount not paid yet ("Total approved, not yet paid", "noch nicht überwiesen")
const NOT_PAID_YET = /\bnicht (?:\w+ ){0,3}(?:überwiesen|bezahlt|gezahlt|beglichen|angewiesen)\b|\bnot (?:yet )?(?:been )?(?:paid|transferred|remitted|settled)\b/i;
const WEAK_KEYWORDS = /betrag|zahlung|überweisung|ueberweisung|amount|payment|bedrag|betaling|montant|paiement|importo|pagamento|importe|\bpago\b|valor|kwota|płatnoś|částka|platba|úhrada|beløb|belopp|betalning|règlement|reglement/i;
// labels of amounts that are no payment: deductions, invoice and gross amounts, balances, order values, a claim filed in
// an insolvency ("Angemeldet gesamt", "amount claimed")
const NEGATIVE_KEYWORDS = /skonto|abzug|abzgl|abzüglich|\.\/\.|einbehalt|gebühr|spesen|rabatt|discount|steuer|mwst|(?:^|[^a-zäöüß])ust(?![a-zäöüß])|(?:^|[^a-z])vat(?![a-z])|rechnungsbetrag|rechnungssumme|bruttobetrag|brutto|netto\b|offener|offene|restbetrag|fällig|iban|bic\b|datum|belegnr|beleg-?nr|rechnungsnr|rechnungs-?nummer|kundennr|kunden-?nummer|lieferantennr|seite|page|telefon|tel\.|fax|steuernummer|ust-id|blz|zwischensumme|subtotal|zinsen|mahn|kontostand|saldo|kapital|capital|kreditlimit|guthaben|kurs\b|umrechnung|exchange rate|gross amount|invoice amount|total invoice|instructed amount|charges|gewicht|menge|übertrag|uebertrag|\bvortrag|carried forward|brought forward|seitensumme|summe seite|delkredere|bonus|provision|aufrechn|bauabzug|quellensteuer|withholding|factuurbedrag|montant (?:de la )?facture|montant ttc|importo (?:della )?fattura|importe (?:de la )?factura|kwota faktury|částka faktury|fakturabeløb|fakturabelopp|korting|escompte|remise|sconto|descuento|\brabat\b|sleva|\bbtw\b|\btva\b|\biva\b|\bbruto\b|\bbrut\b|lordo|retenue|ritenuta|retención|à payer|a payer|te betalen|da pagare|a pagar|do zapłaty|k úhradě|k zaplacení|at betale|att betala|amount due|balance due|total due|auftragswert|auftragssumme|bestellwert|bestellsumme|vertragssumme|projektsumme|order total|order value|total order|contract (?:value|total|sum)|(?:available|account|closing|current|new|opening|ledger) balance|balance after|angemeldet|amount claimed|claimed amount|admitted claim|claim (?:filed|admitted)/i;
// the amount of a claim filed in an insolvency or under a policy ("Angemeldet gesamt", "Your claim as admitted",
// "Gesamtforderung lt. Tabelle", "Amount claimed"; not a claim total of a payer's instalment letter, "Gesamtforderung
// (Rechnungen 2609765, 2610069)"): no payment, unless a payment word comes first and the claim is only its basis
// ("Dividend paid on your admitted claim", "Payment of your claim")
const CLAIM_LABEL = /angemeldet|amount claimed|claimed amount|admitted claim|claim (?:filed|admitted|as admitted)|(?:^|[^a-z])your claim\b(?! (?:no|number|ref|reference)\b)|forderung (?:lt\.?|laut|gem\.?|gemäß) (?:der )?tabelle/i;
const CLAIM_LABEL_G = new RegExp(CLAIM_LABEL.source, "gi");
// deduction labels for the total - deduction = payment chain
const DEDUCTION_KEYWORDS = /skonto|abzug|abzgl|abzüglich|\.\/\.|einbehalt|gebühr|spesen|rabatt|discount|kürzung|gekürzt|kürzen|minderung|verrechn|aufrechn|gutschrift(?!sbetrag|sanzeige| auf)|credit note|less\b|charges|delkredere|bonus|provision|bauabzug|quellensteuer|withholding|zuschuss|rückvergütung|kostenbeteiligung|korting|escompte|remise|sconto|descuento|\brabat\b|sleva|retenue|ritenuta|retención|potrącen|srážka|fradrag|avdrag|^\s*(?:price |pricing |invoice |other )?adjustments?(?: amount)?\s*:?\s*$/i;
const UNIT_AFTER = /^\s?(?:kg|g|t|to|st|stk|stck|stück|pal|paletten|m|m2|m3|qm|cbm|l|ltr|liter|km|std|min|%|prozent|pct|pcs|pc|ea|lbs?)(?![A-Za-zÄÖÜäöüß0-9])/i;
const UNIT_AFTER_H = /^\s?h(?![A-Za-zÄÖÜäöüß0-9])/; // hours, lower case only
// (a whole word, except "nr" as in "Rechnungsnr." - "zapłacono" / "uhrazeno" are no "No.")
// a part payment named as what is paid ("Anzahlung", "Abschlagszahlung", "down payment")
const PART_PAYMENT = /deposit|vorauszahlung|anzahlung|abschlagszahlung|teilzahlung|vorzahlung|ratenzahlung|restzahlung|schlusszahlung|down payment|advance payment|partial payment|instal{1,2}ment/i;
// a row of a list of payments marked as the payment made now, the mark a note of its own after a dash, a bracket, a colon
// or a cell gap ("Instalment 3 - this payment", "Schlusszahlung nach Abnahme – heutige Überweisung", "2. Abschlag – diese
// Zahlung", "Final payment - today's payment", "Schlusszahlung (lt. diesem Avis)", "– heute überwiesen", "(with this
// remittance)"), not words a preposition or a negation governs ("Restbetrag nach dieser Zahlung", "Balance due after this
// payment", "strittig – nicht Bestandteil dieser Zahlung", "not included in this payment", "Fee for this transfer"); what
// makes a row of such a list: a date or a payment word ("Anzahlung 30 %", "2. Rate", "Instalment 1 (paid)"); what makes
// its total a total of payments ("Summe Zahlungen", "Total paid to date"); a fee or charge row is never the payment
const CURRENT_ROW = /(?:^|\s{2,}|[–—(\[\/:;,]\s*|\s-\s*)(?:(?:this|today['\u2019]?s|current|present)\s+(?:payment|transfer|remittance|instal{1,2}ment|wire)\b|(?:diese|heutige|aktuelle|jetzige|vorliegende)\s+(?:zahlung|überweisung|ueberweisung|rate|teilzahlung|abschlagszahlung|restzahlung|schlusszahlung)(?![a-zäöüß])|heute\s+(?:überwiesen|ueberwiesen|bezahlt|gezahlt|angewiesen)(?![a-zäöüß])|(?:paid|transferred|remitted|sent)\s+today\b|(?:laut|lt\.?|gemäß|gem\.|mit|per)\s+(?:diesem|vorliegendem)\s+(?:zahlungs)?avis(?![a-zäöüß])|(?:mit|per|durch)\s+(?:der\s+)?(?:heutigen|vorliegenden)\s+(?:zahlung|überweisung|ueberweisung)(?![a-zäöüß])|(?:with|by|per|as per)\s+(?:this|today['\u2019]?s)\s+(?:payment|transfer|wire|remittance(?:\s+advice)?|payment advice|advice)\b)/i;
const PAID_TOTAL = /zahlung|überweisung|ueberweisung|gezahlt|bezahlt|geleistet|überwiesen|ueberwiesen|\bpayments?\b|\bpaid\b|transfer|remitt/i;
const FEE_ROW = /gebühr|gebuehr|entgelt|spesen|kosten|provision|\bfees?\b|\bcharges?\b|\bcommission\b|\bcosts?\b/i;
// a row of such a list marked as a payment made before ("Check no. 10474, cashed 10/05/2026", "Verrechnungsscheck,
// eingelöst am 05.10.2026", "Instalment 1 (paid)", "bereits überwiesen"), a total of payments named by its period
// ("Payments made to date", "Geleistete Zahlungen", "bisher gezahlt"), and a sentence that says which instalment was paid
// ("we have paid instalment 3 ... today", "haben wir heute die 3. Rate ... überwiesen"; groups 1-5: its number or ordinal
// word) without a negation, a due date or a later payment in it
const EARLIER_ROW = /eingelöst|eingeloest|vereinnahmt|\bcashed\b|\bencashed\b|\bcleared\b|bereits (?:gezahlt|bezahlt|überwiesen|ueberwiesen|erhalten|geleistet)|already (?:paid|received|cashed|cleared)|previously paid|\((?:paid|bezahlt)\)/i;
const PAID_TO_DATE = /\bto date\b|bis dato|bis heute|bisher|geleistete|\bmade\b/i;
const INSTALMENT_PAID = /\b(?:paid|transferred|remitted|sent|settled|wired)\s+(?:the\s+|our\s+)?(?:instal{1,2}ment|tranche)\s+(?:no\.?\s*)?(\d{1,2})(?![\d,])|\b(?:paid|transferred|remitted|sent|settled|wired)\s+(?:the|our)\s+(?:(\d{1,2})(?:st|nd|rd|th)|(first|second|third|fourth|fifth|sixth|seventh|eighth|ninth|tenth))\s+(?:instal{1,2}ment|tranche)\b|(?:^|[^a-zäöüß])(?:die|unsere)\s+(?:(\d{1,2})\.|(erste|zweite|dritte|vierte|fünfte|sechste|siebte|achte|neunte|zehnte))\s*(?:rate|teilrate|teilzahlung|abschlagszahlung|abschlag|tranche)(?![a-zäöüß])[^.!?\n]{0,100}?(?:überwiesen|ueberwiesen|bezahlt|gezahlt|angewiesen|beglichen)(?![a-zäöüß])/i;
const INSTALMENT_NOT_NOW = /\b(?:nicht|not|nächste|naechste|next|wird|werden|will|shall|fällig|faellig|due|scheduled|geplant|vorgesehen|letzte[nm]?|vorige[nm]?|bereits|schon|last|previous|previously|earlier|already)\b/i;
// the payer's own payment named in its sentence ("our payment of EUR 7,091.86", "unsere Zahlung über 7.091,86 EUR") and a
// rounding named in a document ("Rundungsdifferenz", "rounding difference")
const OWN_PAYMENT = /\b(?:our|my)\s+(?:payment|transfer|remittance|wire)\b|(?:^|[^a-zäöüß])(?:unsere|meine)[rn]?\s+(?:zahlung|überweisung|ueberweisung)(?![a-zäöüß])/i;
const ROUNDING_WORD = /rundung|gerundet|rounding|rounded/i;
const PAY_ROW_WORD = /\b\d{1,2}[.\/-]\d{1,2}[.\/-]\d{2,4}\b|\b\d{1,2}\.?\s+(?:jan|feb|mär|mar|apr|mai|may|jun|jul|aug|sep|okt|oct|nov|dez|dec)[a-zä]*\.?\s+\d{4}\b|zahlung|überweisung|ueberweisung|\brate\b|payment|transfer|remittance|deposit|instal{1,2}ment/i;
// the text between a part payment and its amount ("Anzahlung 30 %: 11.873,82", "deposit of $15,385.00", "Anzahlung in
// Höhe von 11.873,82 EUR", "Installment 2 of 4 ($1,575.00)"), and words before it that make it a deduction or an earlier payment ("abzüglich der bereits
// geleisteten Anzahlung", "less deposit received")
const PART_TO_AMOUNT = /^\s*(?:(?:no\.?|nr\.?|#)?\s*\d{1,2}\s*(?:of|von|\/)\s*\d{1,2}\s*)?(?:\(?\s*\d{1,3}(?:[.,]\d+)?\s?%\s*\)?)?\s*(?:of|von|in höhe von|i\.?\s?h\.?\s?v\.?|über|ueber|amounting to|totall?ing|in the amount of|for)?\s*(?:\(?\s*\d{1,3}(?:[.,]\d+)?\s?%\s*\)?)?\s*:?\s*\(?\s*(?:eur|usd|gbp|chf|€|\$|£)?\s*$/i;
const PART_DEDUCTED = /abz(?:gl|üglich|ueglich)|\babzug|\bminus\b|\bless\b|bereits|\bschon\b|erhalten|geleistet|vereinnahmt|received|previous|prior|earlier|already|verrechnet|offset|\bnach (?:der|unserer|ihrer)\b|\bafter (?:the|our|your)\b/i;
// the rest of an invoice held back over a complaint, a check or a dispute ("Transportschäden", "nach Prüfung", "until
// the defect is resolved")
const REST_HELD = /nach (?:prüfung|klärung|abschluss der prüfung)|bis zur (?:klärung|prüfung|behebung)|schäden|schaden|beschädig|mängel|mangelhaft|defekt|reklam|beanstand|einbehalt|zurückbehalt|after (?:review|inspection|clarification|the (?:review|inspection|claim))|until (?:clarified|resolved|the (?:issue|defect|damage|claim))|damage|defect|dispute|withh[eo]ld|complaint/i;
// a payment made twice or too much ("paid twice", "doppelt überwiesen", "duplicate payment", "Überzahlung"), and a request
// for the money back ("please refund", "erstatten Sie", "as a credit to our next invoice")
const DUPLICATE_PAY = /\b(?:paid|bezahlt|überwiesen|ueberwiesen|gezahlt|beglichen|settled|transferred|remitted)\s+(?:[a-zäöüß]+\s+){0,2}?(?:twice|doppelt|zweimal|zweifach|two times|in duplicate)\b|\b(?:twice|doppelt|zweimal) (?:paid|bezahlt|überwiesen|ueberwiesen|gezahlt|beglichen)\b|\bdoppel(?:te|ten|ter)? (?:zahlung|überweisung|bezahlung|buchung)|doppelzahlung|\bduplicate (?:payment|transfer|remittance)s?\b|\bdouble (?:payment|transfer)s?\b|\boverpa(?:id|yment)s?\b|überzahl(?:t|ung)|\bzu viel (?:bezahlt|gezahlt|überwiesen)|\bpaid (?:too much|in excess)\b/i;
const REFUND_ASK = /\brefund|reimburs|\b(?:please|kindly|could you|can you|would you)\s+(?:credit|return|send back|pay back|transfer back)|erstatt|zurücküberweis|zurückzahl|zurück überweisen|rücküberweis|\bgutschreiben\b|als gutschrift|as a credit|\bcredit (?:it|this|the (?:amount|difference|overpayment|duplicate))\b|verrechnen sie|\bpay (?:it |us )?back\b/i;
// a company's share capital right before an amount (legal footer "Grundkapital 25.000.000,00 EUR"): never a payment
const CAPITAL_BEFORE = /(?:(?:grund|stamm|aktien|kommandit|haft)kapital|gezeichnetes kapital|share capital|capital stock|capital social|capitale sociale|kapitał zakładowy|maatschappelijk kapitaal|geplaatst kapitaal|základní kapitál)\s*(?:(?:von|of|de|in höhe von)\s+)?[:=]?\s*(?:EUR|€|CHF|USD|GBP|PLN|zł|CZK|Kč)?\s*$/i;
const NUMBER_LABEL_BEFORE = /(?:nr|(?:^|[^a-zäöüßà-ž])(?:no|rg|re|rechnung|pos|position|beleg|invoice|inv|art|artikel|kd|kunde|anzahl|menge|stk|stück)|#)\.?:?\s*$/i;
// (the dollars of other countries by their prefix: "A$", "AU$", "S$", "C$", "NZ$", "HK$", "US$")
// a currency without minor units: its amounts have no decimals ("¥4,289,100-", "JPY 1,016,300", "₩ 12,500,000")
const ZERO_DECIMAL_CUR = /¥|￥|₩|\b(?:JPY|KRW)\b/;
// a line that converts an amount into another currency for reference ("approx. EUR 22,041.89 at JPY 175.23 = EUR 1.00",
// "Gegenwert", "exchange rate")
const CONVERSION_REF = /\bfor reference\b|\bapprox(?:imately|\.)?(?=\s|$)|\bequivalent\b|\bequals\b|\bentspricht\b|\bgegenwert\b|\bumgerechnet\b|\b(?:exchange|conversion) rate\b|\bwechselkurs\b|\b(?:TTM|TTS|TTB) rate\b|=\s*(?:EUR|USD|GBP|CHF)\s*1(?:[.,]0+)?\b/i;
const CENT_CUR_AMOUNT = /(?:\b(?:EUR|USD|GBP|CHF|CAD|AUD)|[€$£])\s?-?\d|\d\s?(?:€|\b(?:EUR|USD|GBP|CHF|CAD|AUD)\b)/;
const CURRENCY_TOKEN = /\b(?:EUR|CHF|USD|GBP|PLN|CZK|SEK|DKK|NOK|HUF|RON|BGN|JPY|CNY|CAD|AUD|TRY|SGD|NZD|HKD|ZAR|MXN)\b|\b(?:US|AU|A|SG|S|CA|C|NZ|HK)\$|€|\$|£|¥|zł|Kč|\b[Ee][Uu][Rr][Oo]\b|\bSFr\b|\bFr\.(?= ?\d)/g;
// a dollar currency the document names: its ISO code (only beside an amount, in brackets or after "Currency" / "All amounts
// in", not "CAD drawing"), its prefixed symbol or its name ("Australian dollars", "US Dollar")
const DOLLAR_ISO = /\b(USD|AUD|SGD|CAD|NZD|HKD)\b/g;
const DOLLAR_NAME = /\b(?:(U\.?S\.?|United States|American)|(Australian)|(Singapore)|(Canadian)|(New Zealand)|(Hong Kong)) dollars?\b/i;
const CURRENCY_DECL = /(?:\bcurrency|\bcurr\.|\bccy|währung|waehrung|\bdevise|\bamounts?(?: are)?(?: shown| stated| expressed| quoted| given)? in|\bfigures in|\bbeträge in|\bbetraege in|\bpaid in|\bpayment in)\s*[:=]?\s*\(?\s*$/i;
// the payer's country when the document only writes "$": Australian business number, BSB, "Pty Ltd", a state with its
// four-digit postcode -> AUD; Singapore company number (UEN), "Pte. Ltd.", a six-digit Singapore postcode -> SGD; New
// Zealand business number -> NZD; a Canadian province with its postal code -> CAD; signs of the US (an address with a ZIP
// code, ACH, routing number) keep US dollars
const AU_LAND = /\bABN:?\s*\d{2} ?\d{3} ?\d{3} ?\d{3}\b|\bBSB\b|\bPty\.? Ltd\b|\b(?:NSW|VIC|QLD|WA|SA|TAS|ACT|NT) \d{4}(?!\d)|\bAustralia\b/;
const SG_LAND = /\bPte\.? Ltd\b|\bUEN\b|\bSingapore \d{6}(?!\d)/;
const NZ_LAND = /\bNZBN\b|\bNew Zealand\b/;
const CA_LAND = /\bCanada\b|\bGST\/HST\b|\b(?:AB|BC|MB|NB|NL|NS|ON|PE|QC|SK|YT) [A-Z]\d[A-Z] ?\d[A-Z]\d\b/;
const HK_LAND = /\bHong Kong\b/;
// the amount the payee gets in a money-transfer notice ("Nordwerk Antriebstechnik GmbH gets 1,543.20 EUR", "Recipient
// gets", "They receive", "Nordwerk Antriebstechnik GmbH erhält 5.339,73 EUR"): the transferred amount - after a conversion
// the one in the payee's currency, not what the payer sent or converted
// (also "Recipient gets", "Nordwerk GmbH gets", "Empfänger erhält" in a money transfer service's confirmation)
const RECIPIENT_GETS = /(?:\b(?:recipient|receiver|beneficiary|payee|they|empfänger(?:in)?|zahlungsempfänger|begünstigte[rn]?)|\b(?:gmbh|ag|ltd|limited|inc|llc|plc|kg|se|bv|nv|sarl|sas|srl|spa)\.?)\s+(?:gets|get|receives|receive|will receive|erhält|bekommt)\s*:?\s*$|\b(?:gets|receives|will receive|is receiving|erhält|bekommt)\s*:?\s*$/i;
// the amount an escrow or payment service released, the whole label ("Amount released:", "Net amount released", "Released
// amount"; not "Amount released for payment", an approval)
const RELEASED_LABEL = /^\s*(?:(?:net|total)\s+)?(?:amount|funds|sum)\s+released\b(?!\s+for\b)[^a-z]*$|^\s*released\s+amount\b[^a-z]*$/i;
// an exchange rate or a conversion in a document: its amounts in two currencies are one payment converted
const FX_LINE = /exch(?:ange)?\.? ?rate|\bfx\b|wechselkurs|umrechnungskurs|\bkurs\b|conversion rate|converted (?:at|to|into)|equivalent|gegenwert|countervalue|\d\s?[A-Z]{3}\s?=\s?\d/i;
// the currency in which a document says the transfer itself was made ("Payment method   SEPA credit transfer (EUR)",
// "International wire (USD)", "The transfer was made in euro from our sterling account", "Die Überweisung erfolgte in EUR
// zu Lasten unseres PLN-Kontos", "Funds were remitted in USD"): group 1 / 2 = the currency, a code or a word
const TRANSFER_CURRENCY = /(?:transfer|payment|wire|remittance|funds|remitted|zahlung|überweisung|ueberweisung|überwiesen|ueberwiesen)[^.!?\n]{0,60}?\bin\s+(EUR|euros?|USD|US[- ]dollars?|dollars?|GBP|sterling|pounds?|CHF|Swiss francs?|Franken|PLN|CZK|SEK|NOK|DKK|HUF)\b|(?:payment method|method of payment|payment type|zahlungsart|zahlweg|zahlungsweg|zahlungsweise)[^\n]{0,60}?\((EUR|USD|GBP|CHF|PLN|CZK|SEK|NOK|DKK|HUF)\)/gi;
// an amount in the payer's own book currency ("Payment amount in base currency (GBP)", "Zahlungsbetrag in Hauswährung
// (PLN)"): its debit or ledger value, what the payee receives only where the document names it as the transfer's currency
const BOOK_CURRENCY = /\b(?:base|home|functional|reporting|company|accounting|ledger) currency\b|hauswährung|hauswaehrung|buchungswährung|basiswährung|heimatwährung|berichtswährung|konzernwährung/i;
const US_LAND = /\bU\.?S\.?A\b|\bUnited States\b|\bACH\b|\brouting (?:number|no\b|#)|[A-Za-z.], (?:AL|AK|AZ|AR|CA|CO|CT|DE|FL|GA|HI|ID|IL|IN|IA|KS|KY|LA|ME|MD|MA|MI|MN|MS|MO|MT|NE|NV|NH|NJ|NM|NY|NC|ND|OH|OK|OR|PA|RI|SC|SD|TN|TX|UT|VT|VA|WA|WV|WI|WY|DC) \d{5}(?:-\d{4})?\b/;
// payment wording (the English transfer nouns "wire transfer", "credit transfer" count like German "Überweisung"; a wire
// only as a transfer of money: "we sent a wire", "wired the funds", not "copper wire" or "wire harness"; "transferred" only
// with the reader as the payee: "transferred $1,234.56 to your account", "We have transferred EUR 3,144.36 today for your
// invoice ...", "transferred EUR 2,693.25 today for invoice 2026-10251", not "we transferred your order")
const PAYMENT_MARKER = /payout|paid out|disburse|amount transferred|funds transferred|transfer to (?:your )?bank|zahlung|zahlbetrag|\bzahlen|gezahlt|bezahlt|überw|ueberw|gutschrift|gutgeschrieben|ausgleich|beglichen|begleichen|skonto|payment|remittance|\bpaid\b|remitted|auszahlung|credited|credit advice|incoming payment|check no|check date|check amount|cheque|pay to the order|(?:wire|bank|credit|funds?|money|telegraphic) transfer|transferred\b(?:[^.!?\n]|\.(?=\d)){0,40}?\b(?:to|into) your (?:bank |nominated |designated )?account|\btransferred (?:to )?you (?:the (?:sum|amount) of )?(?:(?:eur|usd|gbp|chf|aud|cad|€|\$|£) ?\d|\d[\d.,']*\d ?(?:eur|usd|gbp|chf|aud|cad|€|\$|£))|\btransferred (?:the (?:sum|amount) of )?(?:(?:eur|usd|gbp|chf|aud|cad|€|\$|£) ?\d|\d[\d.,']*\d ?(?:eur|usd|gbp|chf|aud|cad|€|\$|£))(?:[^.!?\n]|\.(?=\d)){0,60}?\b(?:for|against|in (?:full )?settlement of|to settle) (?:your |the )?(?:invoices?|inv\b|bills?|statement)|wire[- ]?transfer|\b(?:sent|send|sending|made|initiated|released|issued) (?:you )?(?:a|an|the|our) wire\b|\bwired (?:you |us )?(?:the )?(?:funds|money|payment|amount|balance|eur|usd|gbp|chf|€|\$|£|\d)|cash discount|settlement discount/i;
// payment words of other languages: they count only together with a payer statement ("nous avons réglé"), because
// foreign bank statements, payslips and bills use them too
const FOREIGN_PAYMENT_MARKER = /zapłat|betaling|betaald|overgemaakt|paiement|règlement|reglement|réglé|virement|payé|pagamento|bonifico|pagato|\bpago\b|pagado|transferencia|transferência|płatnoś|przelew|zapłac|wpłat|plat[be]|úhrad|uhrazen|zaplacen|betalt|betalning|overført|överför/i;
// non-payment documents named anywhere in the text (when no advice title is found): delivery and shipping notices of
// both languages ("Lieferavis", "delivery advice", "advance shipping notice", "avis de livraison"), direct debits
// ("Lastschrift", "SEPA Direct Debit ... under mandate"), reminders
const NON_PAYMENT_MARKER = /lieferschein|lieferavis|versandavis|versandanzeige|avisierung|anlieferung|despatch advice|dispatch advice|delivery advice|shipping advice|shipment advice|advance ship(?:ping|ment)? notice|despatch note|dispatch note|delivery note|avis de livraison|avis d'expédition|lastschrift|mandatsreferenz|direct debit|mandate reference|creditor identifier|pre-?notification|einziehen|zahlungserinnerung|\bmahnung|angebotssumme|von ihrem konto[^.]{0,40}(?:abgebucht|eingezogen)|(?:debited|collected) from your (?:bank )?account/i;
// title of a payment advice: the document checks below trust it (a title in another language only together with a
// payment statement: "avviso di pagamento" / "aviso de pago" are also bills)
const DE_EN_AVIS_TITLE = /zahlungsavis|payment advice|remittance advice|zahlungsmitteilung|erstattungsmitteilung|gutschriftsanzeige|zahlungsfreigabe|auszahlungsmitteilung|auszahlungsanzeige|regulierungsmitteilung|regulierungsschreiben|schadenregulierung|schadenabrechnung|entschädigungsabrechnung|überweisungsavis|ueberweisungsavis|zahlungsbenachrichtigung|zahlungsanzeige|vergütungsanzeige|verguetungsanzeige|payment notification/i;
const AVIS_TITLE = /zahlungsavis|payment advice|remittance advice|zahlungsmitteilung|erstattungsmitteilung|gutschriftsanzeige|zahlungsfreigabe|auszahlungsmitteilung|auszahlungsanzeige|regulierungsmitteilung|regulierungsschreiben|schadenregulierung|schadenabrechnung|entschädigungsabrechnung|überweisungsavis|ueberweisungsavis|zahlungsbenachrichtigung|zahlungsanzeige|vergütungsanzeige|verguetungsanzeige|payment notification|avis de (?:paiement|virement|règlement|reglement)|betalingsadvies|betalingsbericht|avviso di (?:pagamento|bonifico)|aviso de (?:pago|transferencia|pagamento)|awizo (?:płatności|przelewu|zapłaty)|potwierdzenie (?:wykonania |realizacji )?(?:płatności|przelewu|transakcji)|avízo o platbě|platební avízo|oznámení o (?:platbě|úhradě)|betalingsadvis|betalingsavis|betalningsavi|betaalspecificatie|betalingsspecificatie|betaaladvies|potvrzení o (?:platbě|úhradě|provedení platby)|avízo o platbe|potvrdenie o (?:platbe|úhrade)|maksuilmoitus|maksuerittely|maksuaviisi|fizetési értesítő|átutalási értesítő|aviz de plat[ăa]|confirmare (?:de )?plat[ăa]|ödeme bildirimi/i;
// a payer's payment form named by a stand-alone title line without the word "advice" ("REMITTANCE", "Payment made",
// "PAYMENT VOUCHER", German "AVIS"): an advice title only when nothing else says what the document is, it is no letter
// (a letter is judged by its sentences), has payment wording, no open amount, no payment for later or not made, and does
// not address the reader as the payer ("Your payment to ... has been made" is the reader's receipt); "Avis" alone also
// announces deliveries: not with delivery words
const PAYER_DOC_TITLE = /^(?:remittance|payment (?:made|voucher)|avis)\s*:?$/i;
const READER_PAID = /\byour (?:payment|transfer|remittance)\b|\byou (?:have |had )?(?:paid|sent|made|transferred|remitted)\b|\bihre (?:zahlung|überweisung)\b/i;
const DELIVERY_WORD = /liefer(?!ant)|versand|sendung|abhol|zustell|spedition|palette|avisier|nachnahme|ankunft|warenausgang|wareneingang|\blkw\b|rampe|delivery|shipment|dispatch|despatch/i;
// title of a bank transfer form (order confirmation of the payer's bank, "Avis zur SEPA-Überweisung"; the SWIFT printout
// abbreviates "FIN 103 Single Customer Credt Transfer")
const TRANSFER_TITLE = /überweisung|ueberweisung|ausführungsbestätigung|zahlungsauftrag|payment order|wire transfer|\b(?:international|domestic|outgoing|outbound|foreign currency|fx) wire\b|\bwire (?:payment|receipt|confirmation)\b|transfer confirmation|cred(?:i)?t transfer|\bfin ?103\b|virement|bonifico|transferencia|przelew|převod|swift (?:message |mt ?103 )?copy|swift confirmation|\bmt ?103\b|funds transfers?|application for (?:outward |overseas )?(?:funds transfers?|remittance)|outward remittance|telegraphic transfer/i;
// the payer's online banking confirms a transfer as done, pasted or forwarded as text ("Ihr Überweisungsauftrag wurde
// ausgeführt", "Überweisung ausgeführt", "Transfer completed", "Your payment has been sent"): a title line; with the fields
// payee, IBAN / account and amount it is a bank transfer form like a bank's PDF ("nicht ausgeführt", "failed" are none)
const TRANSFER_DONE_TITLE = /(?:überweisung|ueberweisung|zahlungsauftrag|\bauftrag|\btransfer|\bpayment|\bzahlung|\bwire)[^.!?\n]{0,40}\b(?:ausgeführt|durchgeführt|erfolgreich|executed|completed|successful(?:ly)?|sent|processed)\b|\b(?:ausgeführte|durchgeführte|executed|completed|successful|sent)\b[^.!?\n]{0,10}(?:überweisung|ueberweisung|\btransfer|\bpayment|\bzahlung|\bwire)/i;
// a title naming a transfer to a party ("Überweisung vom 19.10.2026 an ...", "Payment to ..."), the party in group 1
const OWNER_PAY_TITLE = /^\s*(?:überweisung|ueberweisung|zahlung|payment|transfer|remittance|wire transfer)(?:\s+(?:vom|von|am|from|of|on|dated)\s+\d{1,4}[.\/-]\d{1,2}[.\/-]\d{1,4})?\s+(?:an|to)\s+([A-ZÄÖÜ][^:;!?]{2,80}?)\s*$/i;
// a title area that names a plan, a proposal, a preview or a payment on hold ("Ratenplan", "Instalment schedule ...
// (proposal)", "Zahlungsvorschlag", "Status: On hold"): a title naming a transfer there names no transfer made
const PLAN_AREA = /vorschlag|proposal|proposed|entwurf|draft|geplant|planned|(?:^|[^a-zäöüß])plan(?![a-zäöüß])|[a-zäöüß]plan(?![a-zäöüß])|schedule|vorschau|preview|forecast|prognose|on hold|gesperrt|zurückgehalten|angehalten/i;
// a party named with the legal form of a company ("Lindmark Spedition GmbH und Co KG", "Morrow Lift Systems Ltd")
const COMPANY_FORM = /(?:^|[^a-zäöüß])(?:gmbh|ag|kg|ohg|ug|e\.\s?k\.?|se|ltd|limited|inc|llc|llp|corp|plc|bv|b\.v|nv|n\.v|sa|s\.a|sas|sarl|srl|spa|s\.p\.a|oy|gbr|mbh|pty)(?![a-zäöüß])/i;
const TRANSFER_NOT_DONE = /\b(?:nicht|not|kein|keine|no|failed|fehlgeschlagen|abgelehnt|rejected|declined|returned|zurück|storniert|cancell?ed|pending|ausstehend|vorgemerkt|geplant|scheduled)\b/i;
// a transfer stated as done in a notice of the payer's bank or payment service, or by the payer ("Your payment has been
// executed", "Your outgoing wire transfer has been completed", "your transfer #4188 to ... has been sent", "Your money's on
// its way", "Ihre Überweisung ist unterwegs", "Deine Zahlung an ... war erfolgreich", "Auslandzahlung ... ausgeführt",
// "International payment submitted", "The wire ... went out today"); NOTICE_NOT: not done (failed, returned, pending,
// waiting for approval, announced for later)
const NOTICE_DONE = /(?:(?:auslands?|sammel|echtzeit|sofort|sepa-?)?(?:überweisung|ueberweisung|zahlung)(?:en)?(?![a-zäöüß])|(?:sammel|dauer|zahlungs|überweisungs)auftrag(?![a-zäöüß])|\b(?:transfer|payment|wire|remittance)s?\b(?! (?:request|reminder|link|plan|terms|instructions|details|information|advice|notice|schedule|proposal|method|date|due)\b)|\bmoney\b|(?:^|[^a-zäöüß])geld(?![a-zäöüß]))[^.!?\n]{0,80}?(?:^|[^a-zäöüß])(?:ausgeführt|durchgeführt|erfolgreich|abgeschickt|gesendet|versendet|unterwegs|executed|completed|successful(?:ly)?|sent(?! back)|processed|submitted|released|went through|gone through|went out|gone out|on (?:its|the) way)(?![a-zäöüß])/i;
const NOTICE_NOT = /\b(?:nicht|not|kein|keine|no|never|failed|fehlgeschlagen|abgelehnt|rejected|declined|returned|zurück|storniert|cancell?ed|reversed|pending|ausstehend|vorgemerkt|geplant|scheduled|approval|freigabe|genehmigung|authori[sz]ation|will|wird|werden|shall|soll|sollte|being|if|wenn|falls)\b/i;
const ORDER_PAYEE = /(?:^|\n)[ \t]*(?:empfänger|zahlungsempfänger|begünstigter|empfängername|name des empfängers|beneficiary|payee|recipient)(?:[ \t]*name)?[ \t]*:/i;
const ORDER_ACCOUNT = /\biban\b|(?:^|\n)[ \t]*(?:kontonummer|konto-?nr\.?|account(?: number| no\.?)?|acct)[ \t]*:/i;
const ORDER_AMOUNT = /(?:^|\n)[ \t]*(?:betrag|überweisungsbetrag|auftragsbetrag|amount|transfer amount)[ \t]*(?:\((?:eur|chf|usd|gbp|€)\))?[ \t]*:/i;
// (also "Zahlungsbetrag" of a bank's confirmation and the SWIFT field ":32A:" with its description above the value line,
// "Value Date/Currency/Interbank Settled Amount" / "261028EUR17005,12"; any currency code or dollar prefix)
const TRANSFER_FIELD = /^(?:betrag|überweisungsbetrag|ueberweisungsbetrag|auftragsbetrag|transferbetrag|zahlungsbetrag|amount|transfer amount|wire (?:transfer )?amount|payment amount|amount sent|sent amount|montant|importo|importe|kwota|částka|:32a:\s*\d{6}|:32a:\s*(?:value date\s*\/\s*)?(?:currency(?: code)?\s*\/\s*)?(?:interbank )?settled amount|(?:currency (?:&|and) )?interbank settle(?:d|ment) amount|amount remitted|remittance amount|settlement amount)\s*(?:\(?(?:eur|chf|usd|gbp|aud|cad|nzd|sgd|hkd|pln|czk|sek|nok|dkk|huf|(?:us|au|a|nz|c|ca|s|sg|hk)?\$|€|£)\)?)?\s*:?\s*(?:eur|chf|usd|gbp|aud|cad|nzd|sgd|hkd|pln|czk|sek|nok|dkk|huf|(?:us|au|a|nz|c|ca|s|sg|hk)?\$|€|£)?\s*$/i;
// the debit of the payer's account in its bank's transfer form: the transfer amount plus fees, or converted into the
// account currency ("Total debit $16,597.77" beside "Amount 15,192.59 EUR", "Belastung gesamt", "Total Belastung CHF")
const DEBIT_TOTAL = /total debit|amount debited|debit(?:ed)? amount|belastungsbetrag|gesamtbelastung|totalbelastung|belastungstotal|belastung (?:gesamt|insgesamt|total)\b|(?:total|gesamte) (?:der )?belastung/i;
// the fee of a transfer in the payer bank's form ("Entgelt", "Gebühr", "Spesen", "Wire Fee", "charges", "Commission")
const TRANSFER_FEE = /entgelt|gebühr|gebuehr|spesen|\bfees?\b|\bcharges?\b|\bcommission\b|\bprovision\b/i;
// the payer bears all charges of a transfer: the payee gets the full amount ("Spesenregelung OUR – sämtliche Spesen zu
// Lasten Auftraggeber", "Payer pays all charges (OUR)"; the code OUR and SEPA transfers are tested case-sensitively)
const CHARGES_PAYER = /(?:spesen|gebühren|entgelte|kosten)[^.\n]{0,20}zu lasten (?:des )?auftraggebers?|payer pays all charges|all charges (?:are )?(?:paid|borne) by (?:the )?(?:payer|remitter|ordering customer|sender)|charges (?:are )?(?:paid|borne) by (?:the )?(?:payer|remitter|ordering customer|sender)/i;
// fields of a bank posting (two of them make a "Gutschrift" a bank credit, not a supplier credit note); "From account" /
// "Debit account" / "Originator" of an English bank form name the ordering party ("Auftraggeber"), "Payee" the payee
const BANK_FIELD = /buchungstag|buchungsdatum|valuta|wertstellung|auftraggeber|ordering customer|ordering party|originator|from account|debit account|value date|begünstigter|beneficiary|\bpayee\b|zahlungsempfänger|\bempfänger\b|empfänger-iban|iban empfänger|rachunek (?:nadawcy|odbiorcy|zleceniodawcy|beneficjenta)|data (?:operacji|księgowania|waluty)|zleceniodawca|beneficjent|opdrachtgever|begunstigde|valutadatum|rentedatum|donneur d'ordre|bénéficiaire|date de valeur|ordinante|beneficiario|data valuta|ordenante|fecha (?:de )?valor|plátce|účet příjemce|datum zaúčtování|remitter|ordering institution|:50[afk]:|:59[af]?:|:57[a-d]:|:32a:/gi;
// other document types in the title area (first lines of page 1, larger font)
const OTHER_TITLE = /mahnung|zahlungserinnerung|zahlungsaufforderung|letzte aufforderung|forderungsaufstellung|inkassoauftrag|inkassoforderung|mahnbescheid|vollstreckungsbescheid|zahlungsbefehl|payment reminder|reminder\b|overdue|final notice|dunning|\brappel\b|relance|herinnering|aanmaning|sollecito|recordatorio de pago|requerimiento de pago|wezwanie do zapłaty|upomnienie|upomínka|výzva k (?:úhradě|zaplacení)|rykker|påminnelse|påmindelse|stornorechnung|\bstorno\b|rechnungskorrektur|korrekturrechnung|angebot|quotation|\bquote\b|kostenvoranschlag|kostenangebot|\bofferte\b|\bdevis\b|preventivo|presupuesto|nabídka|auftragsbestätigung|auftragsbestaetigung|order confirmation|bestellbestätigung|bestätigung ihrer bestellung|purchase order|bestellschreiben|einkaufsbestellung|bon de commande|orden de compra|ordine d'acquisto|versandbestätigung|versandmitteilung|shipping confirmation|shipment notification|ist unterwegs|wurde versandt|has (?:been )?shipped|lieferschein|lieferavis|versandavis|delivery note|packing list|packliste|arrival notice|notice of arrival|ankunftsmeldung|ankunftsavis|avis d'arrivée|container arrival|bill of lading|frachtbrief|verzollungsavis|zollavis|zollanmeldung|abgabenmitteilung|einfuhrabgaben|zollbescheid|customs (?:clearance|entry|notice|invoice)|import duty|pro-?forma|abschlagsrechnung|teilrechnung|schlussrechnung|vorauszahlungsrechnung|anzahlungsrechnung|gehaltsabrechnung|entgeltabrechnung|lohnabrechnung|verdienstabrechnung|bezügemitteilung|bezügeabrechnung|brutto[/-]netto|lohn- und gehalt|payslip|pay slip|salary (?:statement|slip)|earnings statement|reisekostenabrechnung|reisekosten|spesenabrechnung|travel expense|expense (?:report|claim)|kontoauszug|account statement|bank statement|statement of account|saldenbestätigung|saldenabstimmung|saldenmitteilung|(?:kreditkarten|firmenkarten)abrechnung|abrechnung ihrer (?:firmen)?kreditkarte|ihrer firmenkreditkarte|credit card statement|preisliste|price list|allgemeine (?:geschäfts|verkaufs|liefer|einkaufs)|geschäftsbedingungen|terms and conditions|abholavis|benachrichtigungskarte|nachnahme|zahlungsplan|abschlagsplan|tilgungsplan|ratenplan|proposed (?:payment|repayment|instal?ment) (?:plan|schedule)|self-?bill(?:ed|ing) invoice|self-?billing|gutschriftsverfahren|ratenzahlungsvereinbarung|ratenvereinbarung|teilzahlungsvereinbarung|stundungsvereinbarung|instal?lment (?:plan|agreement|schedule|request)|repayment schedule|(?:antrag auf|request for) (?:ratenzahlung|stundung|(?:an? )?instal?lments?(?: plan)?)|ratenzahlungsantrag|stundungsantrag|lastschrift|vorabankündigung|pre-?notification|rückgabe|rücküberweisung|rückbuchung|zurückgegeben|nicht ausgeführt|abgelehnt|returned|rejected|überweisungsträger|überweisungsvordruck|zahlschein|einzahlungsschein|zahlteil|empfangsschein|payment slip|relevé de compte|relevé bancaire|estratto conto|extracto de cuenta|extracto bancario|rekeningafschrift|bankafschrift|wyciąg bankowy|wyciąg z rachunku|výpis z účtu|bankovní výpis|kontoudtog|kontoutdrag|bulletin de (?:paie|salaire)|fiche de paie|cedolino|busta paga|\bnómina\b|loonstrook|salarisstrook|mise en demeure|ingebrekestelling|pagopa|avis d'échéance|avis de prélèvement|umsatzübersicht|umsatzliste|kontoumsätze|account activity|transaction history|auszahlungsvorschau|payout preview|payout forecast|vorläufige abrechnung|zahlungsvorschlag|delivery advice|shipping advice|shipment advice|advance ship(?:ping|ment)? notice|despatch note|dispatch note|avis de livraison|avis d'expédition|balance confirmation|confirmation of (?:the )?(?:account )?balances?|bonusabrechnung|bonusberechnung|bonusmitteilung|bonus (?:statement|calculation|claim)|rebate (?:statement|calculation|claim)|^(?:freundliche |kleine |höfliche |letzte )?erinnerung\b|\b(?:trainingsdokument|schulungsunterlagen?|schulungsdokument|benutzerhandbuch|bedienungsanleitung|leitfaden|merkblatt|user (?:guide|manual)|training (?:document|material|guide))\b/i;
// a certificate as a title (TAX_CERT_TITLE) about tax (TAX_CERT_WORD): "TDS Certificate", "Withholding tax certificate",
// "Steuerbescheinigung", "Freistellungsbescheinigung nach § 48b EStG" (not "Payment Certificate No. 5", "Certificate No.")
const TAX_CERT_TITLE = /^(?:[a-zäöüß-]*bescheinigung|(?:(?:tds|tax|withholding|wht|deduction|residence|residency|exemption|income[- ]tax)[ -]){0,3}certificate|certificat|certificado|certificato)(?![a-zäöüß])(?!\s*(?:no\b|nr\b|number|#))/i;
const TAX_CERT_WORD = /steuer|\btax|\btds\b|withholding|\bwht\b|abzug|deduct|§\s*\d|\bsection\s+\d|\bu\/s\s*\d|residen|ansässig|freistellung|exemption/i;
// a title word right after one of these refers to another document ("Zahlung zu Ihrer Schlussrechnung")
const REF_BEFORE = /(?:\b(?:ihre?[rsmn]?|unsere?[rsmn]?|zu[rm]?|gem(?:äß|\.)|gemaess|lt\.?|laut|bezug|betreff|betr\.?|für|your|our|re|regarding|per|ref\.?)|(?:zahlung|ausgleich|begleichung|überweisung|regulierung|auszahlung|payment|settlement)(?:\s+(?:zu[rm]?|für|auf|der|des|von|of|for))?)(?:\s*\d{1,2}\.)?[\s:]*$/i;
// documents a payer cites as the reference of a payment ("Lieferschein-Nr.", subject "Lieferschein 80012345"):
// outside a stand-alone title they do not make the document another type when the payer states the payment
const REF_DOC = /^(?:lieferschein|delivery note|auftragsbestätigung|auftragsbestaetigung|order confirmation|abschlagsrechnung|teilrechnung|schlussrechnung)$/i;
// (also the delivery itself, named as the reason of a deduction: "Beim Getriebemotor war das Gehäuse bei Anlieferung
// gerissen")
const DELIVERY_REF = /lieferschein|delivery note|anlieferung/gi;
const REMINDER_REF = /zahlungserinnerung|(?:^|[^a-zäöüß])mahnung/gi;
// a payment on account that the writer of a bill received and deducts ("abzgl. Abschlagszahlung vom 15.10.2026
// (erhalten)", "abzüglich erhaltene Anzahlung", "less deposit received"; see onAccountReceived)
const ON_ACCOUNT_RECEIVED = /(?:^|[^a-zäöüß])(?:erhaltene[nr]?|vereinnahmte[nr]?) (?:anzahlung|abschlagszahlung|abschlag|vorauszahlung|akontozahlung)(?:en)?(?![a-zäöüß])|(?:^|[^a-zäöüß])(?:anzahlung|abschlagszahlung|abschlag|vorauszahlung|akontozahlung)(?:en)?(?![a-zäöüß])[^\n()]{0,60}\((?:bereits )?(?:erhalten|eingegangen|vereinnahmt)\)|\b(?:deposit|advance payment|payment on account|down ?payment|progress payment|interim payment)s? (?:already )?received\b/i;
// a delivery document that a payment list names in a remark ("matched to delivery note LS-2026-70988", "abgeglichen mit
// Lieferschein LS-2026-4410"; see listedPayments)
const LIST_CITED_G = /lieferschein|lieferavis|delivery note|despatch note|dispatch note|anlieferung/gi;
const ORDER_CONFIRM = /auftragsbestätigung|auftragsbestaetigung|order confirmation/i;
// invoice or credit note as the title line ("RECHNUNG", "Fattura n. 118/2026", "Gutschrift Nr. GS-4711")
const ORDER_START = /^(?:bestellung|einkaufsbestellung|purchase order|order|bon de commande|commande|bestelling|inkooporder|ordine|pedido|orden de compra|zamówienie|objednávka|bestilling|indkøbsordre|beställning|inköpsorder)(?![a-zà-ž])/i;
const INVOICE_START = /^(?:rechnung|rechnungskopie|invoice|tax invoice|faktura|facture|factuur|fattura|factura|fatura|duplikat|duplicate)(?![a-zà-ž])/i;
// a heading that names a part of a document after the invoice or order word ("Invoice details", "Invoice list", "Rechnung
// Übersicht", "Invoices paid")
const SECTION_HEAD = /^\S+\s+(?:details?|list(?:ing)?|overview|breakdown|paid|settled|covered|included|übersicht|aufstellung|liste|bezahlt|beglichen)\s*$/i;
// the rest of a title line that holds only one reference field beside the title word ("RECHNUNG      Nummer RE-2026383",
// "INVOICE   No. INV-4711", "RECHNUNG   Datum 07.10.2026"): the title word still stands alone
const TITLE_FIELD = /^(?:(?:rechnungs|invoice|beleg|dokument|document|gutschrift|credit note|bestell|order|auftrags)[- ]?)?(?:nummer|nr\.?|no\.?|number|n°|#|datum|date)\s*:?\s*[A-Z]{0,4}[-\/ ]?\d[\w\/.-]*$/i;
// a statement of a bank account or a ledger: a table header with money out and money in columns ("Paid out | Paid in",
// "Money out | Money in", "Withdrawals | Deposits") or with debit, credit and balance columns ("Debit | Credit |
// Balance", "Soll | Haben | Saldo"); a remittance list has invoice, deduction and payment columns instead
const STMT_OUT_CELL = /^(?:paid out|money ?out|withdrawals?|debits?|soll)(?:\s*\(?(?:eur|gbp|usd|chf|€|£|\$)\)?)?$/i;
const STMT_IN_CELL = /^(?:paid in|money ?in|deposits?|credits?|haben)(?:\s*\(?(?:eur|gbp|usd|chf|€|£|\$)\)?)?$/i;
const STMT_BAL_CELL = /^(?:balance|running balance|saldo|kontostand|solde)(?:\s*\(?(?:eur|gbp|usd|chf|€|£|\$)\)?)?$/i;
const STMT_BANK_CELL = /^(?:paid|money|withdrawal|deposit)/i;
// a statement that starts and ends with the account balance ("Beginning balance on 10/01/2026 ... Ending balance on
// 10/30/2026", "Alter Kontostand ... Neuer Kontostand"): a bank account or ledger statement even without a column header
const OPENING_BALANCE = /\b(?:beginning|opening|previous|starting) balance\b|\bbalance brought forward\b|\balter (?:konto)?stand\b|\banfangssaldo\b|\bsaldo alt\b|\bsaldovortrag\b/i;
const CLOSING_BALANCE = /\b(?:ending|closing|new) balance\b|\bneuer saldo\b|\bbalance carried forward\b|\bneuer (?:konto)?stand\b|\bendsaldo\b|\bschlusssaldo\b|\bsaldo neu\b/i;
// the age bands of an aged open-items list ("Current | 1-30 | 31-60 | 61-90 | Over 90"): what is open, not what is paid
const AGE_BAND_CELL = /^(?:current|not (?:yet )?due|nicht fällig|\d{1,3}\s*[-\u2013]\s*\d{1,3}(?:\s*(?:days|tage))?|(?:over|>|über|more than)\s*\d{2,3}(?:\s*(?:days|tage))?|\d{2,3}\s*\+(?:\s*(?:days|tage))?)$/i;
// the payer column of a list of receipts ("Remitter", "Auftraggeber", "Payer"): receipts from several payers are the
// payee's own bank or ledger record, not one payer's advice
const REMITTER_FIELD = /^\s*(?:\d{2},)?\s*(?:ultimate )?(?:debtor|remitter|ordering (?:customer|party)|originator|auftraggeber|zahler)\s*:\s*(.{3,})$/i;
const LEGAL_FORM = /\b(?:gmbh|ag|kg|ohg|ug|e\.?\s?k|se|ltd|limited|inc|llc|corp|co|plc|bv|nv|sa|sas|srl|spa|ab|as|oy|gbr|mbh)\b\.?/g;
const REMITTER_HEAD = /^(?:remitter(?: name)?|remitting party|auftraggeber(?:name)?|name des auftraggebers|zahler|zahlungspflichtige[r]?|payer(?: name)?|ordering (?:party|customer)|originator(?: name)?|debtor(?: name)?)$/i;
// a periodic statement (not a single transaction shown as proof of payment): statement period, balances brought or
// carried forward, opening and closing balance
const STMT_PERIODIC = /statement period|statement (?:no|nr|number|date)\b|balance (?:brought|carried) forward|balance [bc]\/f\b|(?:opening|closing) balance|account summary|auszugszeitraum|kontoauszug|alter (?:konto)?stand|neuer (?:konto)?stand|saldovortrag|anfangssaldo|endsaldo|schlusssaldo|saldo (?:alt|neu)\b/i;
// a tear-off remittance slip of a statement or an invoice, to be returned with the reader's own payment ("Detach and
// return with your payment", "Please return this portion with your payment", a blank "Amount enclosed", "Enter the
// amount you are paying", "Bitte abtrennen und mit Ihrer Zahlung einsenden"): its "PAYMENT ADVICE" title is a form for
// a payment the reader still has to make (a payer's cheque stub says "detach and retain")
const REMIT_SLIP = /\b(?:detach|tear off|cut off|cut here)\b[^.\n]{0,40}\b(?:return|send|include|enclose|mail)\b[^.\n]{0,40}\bwith (?:your|the|a) (?:payment|remittance|cheque|check)\b|\b(?:return|send|include|enclose|mail) (?:this|the|bottom|top|lower|upper) (?:portion|part|section|slip|stub|coupon)\b[^.\n]{0,40}\bwith (?:your|the|a) (?:payment|remittance|cheque|check)\b|\bamount enclosed\b(?![^\n]{0,30}\d)|\benter the amount (?:you are paying|paid|enclosed)\b|\b(?:abtrennen|abschneiden)\b[^.\n]{0,60}\b(?:zahlung|überweisung|einsenden|zurücksenden|beilegen)|\bmit (?:ihrer|der) (?:zahlung|überweisung) (?:zurücksenden|einsenden|beilegen|beifügen)\b/i;
// amount-due labels of invoices ("Net à payer", "Totale da pagare", "Amount due")
const DUE_LABEL = /zu zahlen|zahlbar|amount due|balance due|total due|à payer|a payer|te betalen|da pagare|a pagar|do zapłaty|k úhradě|k zaplacení|at betale|att betala/i;
const CREDIT_TITLE = /^(?:gutschrift|lieferantengutschrift|gutschriftsrechnung|credit note|credit memo|creditnota|avoir|nota di credito|nota de crédito|dobropis|kreditnota|faktura korygująca)(?:(?:\s*-?\s*(?:nr\.?|no\.?|n°|nummer|number|#)|\s*:)?\s*(?=[\w\/.-]*\d)[A-Z0-9][\w\/.-]*)?$/i;
// the vendor payment record of accounting software (NetSuite, QuickBooks: "Bill Payment", "Bill Payment Summary") as a
// title line of its own
const BILL_PAYMENT_TITLE = /^bill payments?(?: (?:summary|details|confirmation|notification|stub|voucher|receipt))?$/i;
// a debit note of the customer as the title line ("DEBIT NOTE", "Debit memo DM-4711"; the German "Belastungsanzeige" is
// DEBIT_DOC): it charges the supplier, no payment advice
const DEBIT_TITLE = /^(?:debit note|debit memo)(?:(?:\s*-?\s*(?:no\.?|number|#)|\s*:)?\s*(?=[\w\/.-]*\d)[A-Z0-9][\w\/.-]*)?$/i;
// credit notes listed in their own block ("Gutschriften", "Gutschrift GS-0007 238,00")
const CREDIT_WORD = /gutschrift(?!sbetrag|sanzeige| auf| aus| erfolgt| sollte| wird)|credit note|credit memo|creditnota|\bavoir\b|nota di credito|nota de crédito|dobropis|kreditnota/i;
const CREDIT_SECTION = /^\s*(?:ihre |unsere |abzgl\.? |abzüglich |\.\/\. )?(?:gutschriften|gutschrift|credit notes?|credit memos?|creditnota'?s?|avoirs?|note di credito|notas de crédito)\s*:?\s*$/i;
// the document naming itself ("Rückfragen zu diesem Zahlungsavis", "queries regarding this remittance advice"): removed
// before REQUEST_ADVICE is tested
const SELF_ADVICE = /\b(?:dies(?:e[mnrs]?)?|this|our|unser(?:e[mnrs]?)?)\s+(?:zahlungsavis|avis|remittance(?:\s+advice)?|payment advice)\b/gi;
// advice words in the plural name advices or payments in general ("Remittance advices will be e-mailed after each payment
// run", "for all future remittances", "Zahlungsavise senden Sie bitte an ..."), not the document itself: removed before
// an advice title or word is looked for in running text
const ADVICE_PLURAL = /\b(?:remittance advices|payment advices|remittances|zahlungsavise)\b/gi;
// a word that puts an advice title into the future ("Future Remittance Advices", "künftige Zahlungsavise")
const FUTURE_QUALIFIER = /(?:future|künftige[nrs]?|upcoming|kommende[nrs]?)\s*$/i;
// an advice cited as the reference of a field or a statement ("Creditor Number (As per your Remittance Advice)", "laut
// Ihrem Zahlungsavis") or as the document to check a receipt against ("please check it against the remittance advice",
// "bitte mit dem Avis abgleichen"): another document, not the title of this one
const ADVICE_REF = /\b(?:as per|according to|see|siehe|laut|lt\.?|gemäß|gem\.)\s+(?:(?:your|our|the|ihre[mnrs]?|unsere[mnrs]?|de[mnrs]|die|das)\s+)?(?:remittance advice|payment advice|zahlungsavis|avis)\b|\b(?:check|compare|reconcile|match|verify)\b(?:[^.!?\n]|\.(?=\d)){0,40}?\b(?:against|with)\s+(?:(?:the|their|your|our|its|a|an)\s+)?(?:remittance advice|payment advice|remittance)\b|\b(?:mit|gegen)\s+(?:dem|das|ihrem|deren|dessen|seinem|unserem|einem)\s+(?:zahlungs)?avis\s+(?:abgleichen|abstimmen|vergleichen|prüfen|pruefen|überprüfen)(?![a-zäöüß])/i;
const ADVICE_REF_G = new RegExp(ADVICE_REF.source, "gi");
// an advice announced for later ("A remittance advice will be sent once the payment has been released", "remittance
// advice to follow", "Nach dem Zahllauf erhalten Sie ein Zahlungsavis", "das Avis folgt", "You will receive a separate
// remittance advice once the payment has been executed", "Sie erhalten ein gesondertes Zahlungsavis, sobald ..."): it names
// a later document, not this one; removed like the plural (not "Sie erhalten hiermit / heute / anbei unser Zahlungsavis
// nach dem Zahllauf vom 30.10.2026", which is this advice)
const FUTURE_ADVICE = /\b(?:a|an|the|our|your)\s+(?:[a-z-]+\s+){0,2}?(?:remittance|payment) advice\s+(?:will|shall|is going to)\s+(?:be\s+)?(?:sent|e-?mailed|mailed|issued|provided|forwarded|follow|available)\b[^.!?\n]*|\b(?:remittance|payment) advice\s+(?:to follow|will follow|follows)\b[^.!?\n]*|\byou(?: will|['\u2019]ll) (?:then |also |shortly |subsequently |soon )?receive (?:a|an|the|our) (?:[a-z-]+ ){0,2}?(?:remittance|payment) advice\b[^.!?\n]*|\bsie (?:erhalten|bekommen)\b(?!\s+(?:[a-zäöüß]+\s+){0,2}?(?:hiermit|heute|anbei|anliegend|beiliegend|nachstehend|nachfolgend|untenstehend|unten|im anhang|in der anlage|als anlage|mit dieser)\b)(?=[^.!?\n]{0,100}\b(?:sobald|nachdem|nach (?:ausführung|dem|der|erfolgter)|separat|separates|gesondert|gesondertes)\b)[^.!?\n]{0,60}?\b(?:zahlungsavis|avis)\b[^.!?\n]*|\b(?:nach (?:dem|der|erfolgter|ausführung)[^.!?\n]{0,40}?|später|separat|gesondert|in kürze|demnächst|zeitnah)\s+(?:erhalten|bekommen) sie\b[^.!?\n]{0,40}?\b(?:zahlungsavis|avis)\b[^.!?\n]*|\b(?:erhalten|bekommen) sie\s+(?:[a-zäöüß]+\s+){0,3}?(?:nach (?:dem|der|erfolgter|ausführung)|später|separat|gesondert|in kürze|demnächst|zeitnah)\b[^.!?\n]{0,40}?\b(?:zahlungsavis|avis)\b[^.!?\n]*|\b(?:das|ein|unser)\s+(?:zahlungsavis|avis)\s+(?:folgt|kommt|wird (?:ihnen )?(?:[a-zäöüß]+ ){0,2}?(?:folgen|nachgereicht|zugesandt|zugeschickt|übermittelt|gesendet|versandt))\b[^.!?\n]*/gi;
// an advice that someone is asked for, that is to be requested or that nobody has ("I'll ask them for the remittance
// advice", "has anyone seen the remittance?", "Does anyone have their remittance advice?", "ich frage den Kunden nach dem
// Avis", "Hat jemand von euch schon ein Avis dazu?", "Zahlungsavis Rennwald Bau anfordern"): a missing advice, not the
// title or the advice word of this text; removed like the plural. Not when the writer's own side was asked ("asked my
// colleague for the remittance advice", "fragte unsere Buchhaltung nach dem Zahlungsavis") or the text hands it over right
// after ("..., so here it is:", "- hier ist es:"): the writer answers with the advice (the reader asked by the writer, "you
// asked us for the remittance advice", is no such phrase either)
const ADVICE_SOUGHT = /\b(?:ask|asks|asked|asking|chase|chases|chased|chasing|remind|reminded)\s+(?!(?:you|us|me|for|my|our)\b)(?:[^\s!?,;:]+\s+){1,3}?for\s+(?:(?:a|an|the|their|his|her|its|any)\s+)?(?:copy of (?:the |their |a |an )?)?(?:remittance(?:\s+advice)?|payment advice)\b(?!(?:[^.!?\n]|\.(?=\d)){0,80}?(?:\bhere (?:it is|they are|you are|are the|is the)\b|\bso here\b|\bplease find\b|\bbelow\b))|\b(?:has|have|did|does|do)\s+(?:anyone|anybody|someone|somebody)(?:\s+(?:here|else))?\s+(?:seen|got|gotten|received|found|had|have|get)\s+(?:(?:a|an|the|their|his|her|its|any)\s+)?(?:remittance(?:\s+advice)?|payment advice)\b|\b(?:frage|fragen|fragt|frag|fragte|fragten)\s+(?!(?:sie|uns|mich|nach|unser(?:e[mnrs]?)?|mein(?:e[mnrs]?)?)\b)(?:[a-zäöüß.'-]+\s+){1,3}?nach\s+(?:dem|einem|ihrem|seinem|deren|dessen)\s+(?:zahlungs)?avis\b(?!(?:[^.!?\n]|\.(?=\d)){0,80}?(?:\bhier (?:ist|sind|kommt|kommen|finden sie)\b|(?:^|[^a-zäöüß])(?:anbei|nachstehend|nachfolgend|untenstehend)(?![a-zäöüß])))|\b(?:hat|hatte)\s+(?:jemand|wer|irgendwer|irgendjemand)\s+(?:(?:von euch|von ihnen|hier|schon|bereits|denn|vielleicht|zufällig|inzwischen|mittlerweile)\s+){0,3}(?:ein|das|sein|ihr|deren|dessen)\s+(?:zahlungs)?avis\b|\b(?:zahlungs)?avis\b(?:[^.!?\n]|\.(?=\d)){0,40}?(?:^|[^a-zäöüß])(?:anfordern|anzufordern|nachfordern|einholen|einzuholen)(?![a-zäöüß])/i;
