const DATE_DOT = /\b(\d{1,2}\.\d{1,2})\.(?=[ \t]+(?:[a-zäöüß\d€$£(]|(?:EUR|CHF|USD|GBP)\b|Ihr(?:e[mnrs]?)?\b|Ihnen\b))/g;
