const FUTURE_SENT = /\b(?:werden|wird|will|shall)\b|nächste|naechste|kommende|künftig|später|sobald|\bnach (?:klärung|eingang|prüfung|erhalt|abschluss)|\bnext\b|\blater\b|\bonce\b|\bupon\b/i;
